//! Articles, frontmatter, transaction logs, snippets, tag ontology and settings.
//!
//! Layout of the data folder (it is also the Git repository that gets synced):
//!
//! ```text
//! <data>/content/2026/11/22/<slug>/index.md          one article (Hugo page bundle)
//! <data>/transactions/2026/11/2026-11-22_<client>.json   what changed that day on that client
//! <data>/snippets.json                                snippets collected via right-click
//! <data>/tags.json                                    tag ontology (child -> parent)
//! ```

use chrono::{DateTime, Local, NaiveDateTime, TimeZone};
use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};

pub const CONTENT_DIR: &str = "content";
pub const TX_DIR: &str = "transactions";

// ---------------------------------------------------------------- settings

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(default)]
pub struct Config {
    pub data_dir: PathBuf,
    pub repo_url: String,
    pub branch: String,
    pub client: String,
    /// RFC 3339 time of the last successful sync.
    pub last_sync: Option<String>,
}

impl Default for Config {
    fn default() -> Self {
        let docs = dirs::document_dir()
            .or_else(dirs::home_dir)
            .unwrap_or_else(|| PathBuf::from("."));
        Config {
            data_dir: docs.join("Microblog"),
            repo_url: String::new(),
            branch: "main".into(),
            client: default_client_name(),
            last_sync: None,
        }
    }
}

fn default_client_name() -> String {
    let host = std::env::var("HOSTNAME")
        .ok()
        .or_else(|| {
            std::process::Command::new("hostname")
                .output()
                .ok()
                .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
        })
        .unwrap_or_else(|| "client".into());
    let s = slugify(host.split('.').next().unwrap_or("client"), 24);
    if s.is_empty() {
        "client".into()
    } else {
        s
    }
}

pub fn config_path() -> PathBuf {
    dirs::config_dir()
        .unwrap_or_else(|| PathBuf::from("."))
        .join("Microblog")
        .join("config.json")
}

pub fn load_config() -> Config {
    fs::read_to_string(config_path())
        .ok()
        .and_then(|s| serde_json::from_str(&s).ok())
        .unwrap_or_default()
}

pub fn save_config(cfg: &Config) -> Result<(), String> {
    let p = config_path();
    if let Some(d) = p.parent() {
        fs::create_dir_all(d).map_err(|e| e.to_string())?;
    }
    let s = serde_json::to_string_pretty(cfg).map_err(|e| e.to_string())?;
    fs::write(p, s).map_err(|e| e.to_string())
}

// ---------------------------------------------------------------- articles

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct FrontMatter {
    pub title: String,
    pub date: String,
    pub id: String,
    pub tags: Vec<String>,
    #[serde(rename = "abstract")]
    pub abstract_: String,
    pub draft: bool,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Article {
    pub id: String,
    /// Folder relative to the data folder, e.g. `content/2026/11/22/hallo-welt`.
    pub rel_dir: String,
    pub title: String,
    /// Local time, edited as `YYYY-MM-DD HH:MM`.
    pub date: NaiveDateTime,
    pub tags: Vec<String>,
    pub abstract_: String,
    pub body: String,
    pub draft: bool,
}

impl Article {
    pub fn file(&self, data: &Path) -> PathBuf {
        data.join(&self.rel_dir).join("index.md")
    }

    pub fn to_markdown(&self) -> String {
        let fm = FrontMatter {
            title: self.title.clone(),
            date: format_date_rfc3339(&self.date),
            id: self.id.clone(),
            tags: self.tags.clone(),
            abstract_: self.abstract_.clone(),
            draft: self.draft,
        };
        let yaml = serde_yaml::to_string(&fm).unwrap_or_default();
        let mut out = String::from("---\n");
        out.push_str(&yaml);
        if !yaml.ends_with('\n') {
            out.push('\n');
        }
        out.push_str("---\n\n");
        out.push_str(self.body.trim_end());
        out.push('\n');
        out
    }
}

pub fn format_date_rfc3339(d: &NaiveDateTime) -> String {
    match Local.from_local_datetime(d).single() {
        Some(dt) => dt.to_rfc3339_opts(chrono::SecondsFormat::Secs, false),
        None => d.format("%Y-%m-%dT%H:%M:%S").to_string(),
    }
}

pub fn parse_date(s: &str) -> Option<NaiveDateTime> {
    let s = s.trim();
    if let Ok(dt) = DateTime::parse_from_rfc3339(s) {
        return Some(dt.with_timezone(&Local).naive_local());
    }
    for f in ["%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%dT%H:%M"] {
        if let Ok(d) = NaiveDateTime::parse_from_str(s, f) {
            return Some(d);
        }
    }
    chrono::NaiveDate::parse_from_str(s, "%Y-%m-%d")
        .ok()
        .and_then(|d| d.and_hms_opt(0, 0, 0))
}

pub fn parse_article(text: &str, rel_dir: &str) -> Article {
    let text = text.trim_start_matches('\u{feff}');
    let (fm, body) = split_frontmatter(text);
    let fm: FrontMatter = fm
        .and_then(|y| serde_yaml::from_str(y).ok())
        .unwrap_or_default();
    let date = parse_date(&fm.date)
        .or_else(|| date_from_dir(rel_dir))
        .unwrap_or_else(|| Local::now().naive_local());
    let id = if fm.id.trim().is_empty() {
        id_from_dir(rel_dir)
    } else {
        fm.id.trim().to_string()
    };
    Article {
        id,
        rel_dir: rel_dir.to_string(),
        title: fm.title,
        date,
        tags: normalize_tags(&fm.tags),
        abstract_: fm.abstract_,
        body: body.trim_start_matches('\n').to_string(),
        draft: fm.draft,
    }
}

fn split_frontmatter(text: &str) -> (Option<&str>, &str) {
    let t = text.strip_prefix("---\r\n").or_else(|| text.strip_prefix("---\n"));
    if let Some(rest) = t {
        for marker in ["\n---\n", "\n---\r\n"] {
            if let Some(pos) = rest.find(marker) {
                return (Some(&rest[..pos + 1]), &rest[pos + marker.len()..]);
            }
        }
        if let Some(stripped) = rest.strip_suffix("\n---") {
            return (Some(stripped), "");
        }
    }
    (None, text)
}

/// `content/2026/11/22/slug` -> `2026-11-22-slug`
pub fn id_from_dir(rel_dir: &str) -> String {
    let parts: Vec<&str> = rel_dir.split('/').filter(|p| !p.is_empty()).collect();
    let n = parts.len();
    if n >= 4 {
        format!("{}-{}-{}-{}", parts[n - 4], parts[n - 3], parts[n - 2], parts[n - 1])
    } else {
        parts.join("-")
    }
}

fn date_from_dir(rel_dir: &str) -> Option<NaiveDateTime> {
    let parts: Vec<&str> = rel_dir.split('/').collect();
    let n = parts.len();
    if n < 4 {
        return None;
    }
    let s = format!("{}-{}-{}", parts[n - 4], parts[n - 3], parts[n - 2]);
    parse_date(&s)
}

pub fn normalize_tags(tags: &[String]) -> Vec<String> {
    let mut seen = BTreeSet::new();
    let mut out = Vec::new();
    for t in tags {
        let t = normalize_tag(t);
        if !t.is_empty() && seen.insert(t.clone()) {
            out.push(t);
        }
    }
    out
}

pub fn normalize_tag(t: &str) -> String {
    t.trim()
        .trim_start_matches('#')
        .to_lowercase()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join("-")
}

pub fn slugify(s: &str, max: usize) -> String {
    let mut out = String::new();
    let mut dash = false;
    for c in s.to_lowercase().chars() {
        let rep: &str = match c {
            'ä' => "ae",
            'ö' => "oe",
            'ü' => "ue",
            'ß' => "ss",
            'é' | 'è' | 'ê' => "e",
            'á' | 'à' | 'â' => "a",
            'ó' | 'ò' | 'ô' => "o",
            'í' | 'ì' | 'î' => "i",
            'ú' | 'ù' | 'û' => "u",
            _ => "",
        };
        if !rep.is_empty() {
            out.push_str(rep);
            dash = false;
        } else if c.is_ascii_alphanumeric() {
            out.push(c);
            dash = false;
        } else if !dash && !out.is_empty() {
            out.push('-');
            dash = true;
        }
        if out.len() >= max {
            break;
        }
    }
    out.trim_matches('-').to_string()
}

/// Reads every `index.md` below `content/`.
pub fn load_articles(data: &Path) -> Vec<Article> {
    let mut out = Vec::new();
    let root = data.join(CONTENT_DIR);
    walk(&root, &mut |p| {
        if p.file_name().map(|n| n == "index.md").unwrap_or(false) {
            if let (Ok(text), Some(dir)) = (fs::read_to_string(p), p.parent()) {
                if let Ok(rel) = dir.strip_prefix(data) {
                    let rel = rel.to_string_lossy().replace('\\', "/");
                    out.push(parse_article(&text, &rel));
                }
            }
        }
    });
    out.sort_by(|a, b| b.date.cmp(&a.date).then(b.id.cmp(&a.id)));
    out
}

fn walk(dir: &Path, f: &mut dyn FnMut(&Path)) {
    let Ok(rd) = fs::read_dir(dir) else { return };
    for e in rd.flatten() {
        let p = e.path();
        if p.is_dir() {
            walk(&p, f);
        } else {
            f(&p);
        }
    }
}

/// Creates the folder for a new article, `content/YYYY/MM/DD/<slug>`, unique for that day.
pub fn new_article(data: &Path, title: &str) -> Article {
    let now = Local::now().naive_local();
    let day = now.format("%Y/%m/%d").to_string();
    let mut base = slugify(title, 40);
    if base.is_empty() {
        base = format!("eintrag-{}", now.format("%H%M"));
    }
    let mut slug = base.clone();
    let mut n = 2;
    while data.join(CONTENT_DIR).join(&day).join(&slug).exists() {
        slug = format!("{base}-{n}");
        n += 1;
    }
    let rel_dir = format!("{CONTENT_DIR}/{day}/{slug}");
    Article {
        id: id_from_dir(&rel_dir),
        rel_dir,
        title: title.to_string(),
        date: now,
        tags: vec![],
        abstract_: String::new(),
        body: String::new(),
        draft: false,
    }
}

pub fn save_article(data: &Path, a: &Article) -> Result<(), String> {
    let f = a.file(data);
    if let Some(d) = f.parent() {
        fs::create_dir_all(d).map_err(|e| e.to_string())?;
    }
    fs::write(&f, a.to_markdown()).map_err(|e| e.to_string())
}

pub fn delete_article(data: &Path, a: &Article) -> Result<(), String> {
    let dir = data.join(&a.rel_dir);
    if dir.exists() {
        fs::remove_dir_all(&dir).map_err(|e| e.to_string())?;
    }
    // tidy up empty day/month/year folders
    let mut p = dir.parent().map(|p| p.to_path_buf());
    let stop = data.join(CONTENT_DIR);
    while let Some(d) = p {
        if d == stop || !d.starts_with(&stop) {
            break;
        }
        if fs::remove_dir(&d).is_err() {
            break;
        }
        p = d.parent().map(|p| p.to_path_buf());
    }
    Ok(())
}

// ---------------------------------------------------------------- transactions

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct TxEntry {
    pub time: String,
    pub id: String,
    pub action: String,
    pub path: String,
    #[serde(default)]
    pub title: String,
    #[serde(default)]
    pub client: String,
}

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct TxDay {
    pub date: String,
    pub client: String,
    pub entries: Vec<TxEntry>,
}

fn tx_file(data: &Path, day: &chrono::NaiveDate, client: &str) -> PathBuf {
    data.join(TX_DIR)
        .join(day.format("%Y").to_string())
        .join(day.format("%m").to_string())
        .join(format!("{}_{}.json", day.format("%Y-%m-%d"), client))
}

/// Appends one change to today's transaction file of this client.
/// Several saves of the same article on one day are folded into one entry.
pub fn log_tx(data: &Path, client: &str, a: &Article, action: &str) -> Result<(), String> {
    let now = Local::now();
    let day = now.date_naive();
    let f = tx_file(data, &day, client);
    let mut txd: TxDay = fs::read_to_string(&f)
        .ok()
        .and_then(|s| serde_json::from_str(&s).ok())
        .unwrap_or_default();
    txd.date = day.format("%Y-%m-%d").to_string();
    txd.client = client.to_string();
    let entry = TxEntry {
        time: now.to_rfc3339_opts(chrono::SecondsFormat::Secs, false),
        id: a.id.clone(),
        action: action.to_string(),
        path: format!("{}/index.md", a.rel_dir),
        title: a.title.clone(),
        client: client.to_string(),
    };
    if let Some(last) = txd.entries.iter_mut().rev().find(|e| e.id == a.id) {
        if action == "updated" && (last.action == "updated" || last.action == "created") {
            last.time = entry.time;
            last.title = entry.title;
            write_json(&f, &txd)?;
            return Ok(());
        }
    }
    txd.entries.push(entry);
    write_json(&f, &txd)
}

fn write_json<T: Serialize>(f: &Path, v: &T) -> Result<(), String> {
    if let Some(d) = f.parent() {
        fs::create_dir_all(d).map_err(|e| e.to_string())?;
    }
    let s = serde_json::to_string_pretty(v).map_err(|e| e.to_string())?;
    fs::write(f, s).map_err(|e| e.to_string())
}

/// All transaction entries (from every client) newer than `since`, newest first.
pub fn tx_since(data: &Path, since: Option<&str>) -> Vec<TxEntry> {
    let since = since.and_then(|s| DateTime::parse_from_rfc3339(s).ok());
    let mut out = Vec::new();
    walk(&data.join(TX_DIR), &mut |p| {
        if p.extension().map(|e| e == "json").unwrap_or(false) {
            if let Some(txd) = fs::read_to_string(p)
                .ok()
                .and_then(|s| serde_json::from_str::<TxDay>(&s).ok())
            {
                for mut e in txd.entries {
                    if e.client.is_empty() {
                        e.client = txd.client.clone();
                    }
                    let t = DateTime::parse_from_rfc3339(&e.time).ok();
                    let newer = match (since, t) {
                        (Some(s), Some(t)) => t > s,
                        _ => since.is_none(),
                    };
                    if newer {
                        out.push(e);
                    }
                }
            }
        }
    });
    out.sort_by(|a, b| b.time.cmp(&a.time));
    out
}

// ---------------------------------------------------------------- snippets

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Snippet {
    pub created: String,
    pub text: String,
    #[serde(default)]
    pub source: String,
}

pub fn snippets_path(data: &Path) -> PathBuf {
    data.join("snippets.json")
}

pub fn load_snippets(data: &Path) -> Vec<Snippet> {
    fs::read_to_string(snippets_path(data))
        .ok()
        .and_then(|s| serde_json::from_str(&s).ok())
        .unwrap_or_default()
}

pub fn save_snippets(data: &Path, s: &[Snippet]) -> Result<(), String> {
    write_json(&snippets_path(data), &s)
}

pub fn add_snippet(data: &Path, text: &str, source: &str) -> Result<(), String> {
    let text = text.trim_end();
    if text.trim().is_empty() {
        return Err("leerer Text".into());
    }
    let mut all = load_snippets(data);
    all.insert(
        0,
        Snippet {
            created: Local::now().to_rfc3339_opts(chrono::SecondsFormat::Secs, false),
            text: text.to_string(),
            source: source.to_string(),
        },
    );
    save_snippets(data, &all)
}

// ---------------------------------------------------------------- tag ontology

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct Ontology {
    /// child tag -> parent tag
    pub parents: BTreeMap<String, String>,
}

impl Ontology {
    pub fn load(data: &Path) -> Self {
        fs::read_to_string(data.join("tags.json"))
            .ok()
            .and_then(|s| serde_json::from_str(&s).ok())
            .unwrap_or_default()
    }
    pub fn save(&self, data: &Path) -> Result<(), String> {
        write_json(&data.join("tags.json"), self)
    }
    pub fn parent(&self, t: &str) -> Option<&str> {
        self.parents.get(t).map(|s| s.as_str())
    }
    pub fn children(&self, t: &str) -> Vec<String> {
        self.parents
            .iter()
            .filter(|(_, p)| p.as_str() == t)
            .map(|(c, _)| c.clone())
            .collect()
    }
    /// `t` and everything below it.
    pub fn descendants(&self, t: &str) -> BTreeSet<String> {
        let mut out = BTreeSet::new();
        let mut stack = vec![t.to_string()];
        while let Some(x) = stack.pop() {
            if out.insert(x.clone()) {
                stack.extend(self.children(&x));
            }
        }
        out
    }
    /// Would making `parent` the parent of `child` create a loop?
    pub fn would_cycle(&self, child: &str, parent: &str) -> bool {
        self.descendants(child).contains(parent)
    }
}

// ---------------------------------------------------------------- demo data

/// Writes a few example articles (used for the screenshot when there is no data yet).
pub fn write_demo(data: &Path, client: &str) {
    let samples: [(&str, &str, &[&str], &str, &str); 6] = [
        (
            "Willkommen im Microblog",
            "2026-11-22 09:15",
            &["meta", "notizen"],
            "Kurze Einträge in Markdown schreiben, mit Tags ordnen und per Knopfdruck mit GitHub abgleichen. Jeder Eintrag liegt als eigene Datei im Ordner Content – sortiert nach Jahr, Monat und Tag.",
            "## Schön, dass du da bist\n\nDieser Eintrag zeigt, was **Markdown** kann:\n\n- *kursiv* und **fett**\n- [Links](https://gohugo.io)\n- `Code` im Text\n\n> Ein Zitat sieht so aus.\n\n### Nächste Schritte\n\n1. Oben auf **Neu** klicken\n2. Tags vergeben\n3. Synchronisieren\n",
        ),
        (
            "Hugo-Seite vorbereitet",
            "2026-11-21 18:40",
            &["hugo", "web"],
            "Die Ordnerstruktur passt schon zu Hugo: jeder Eintrag ist ein Page Bundle mit index.md, Frontmatter enthält Titel, Datum, Tags und Abstract.",
            "Die Seite kommt in Stufe 2.\n",
        ),
        (
            "Rust und egui ausprobiert",
            "2026-11-20 21:05",
            &["rust", "programmieren"],
            "Ein kleines Fenster mit Seitenleiste, Liste und Editor. Erstaunlich wenig Code für eine Oberfläche, die sich schnell anfühlt und überall läuft.",
            "```rust\nfn main() {\n    println!(\"Hallo\");\n}\n```\n",
        ),
        (
            "Lesenotiz: Gute Tags",
            "2026-11-19 07:30",
            &["notizen", "lesen"],
            "Tags sind frei vergebbar. Später lassen sie sich ordnen: \"rust\" unter \"programmieren\", \"hugo\" unter \"web\". So bleibt die Seitenleiste übersichtlich und die Suche trotzdem genau.",
            "Ontologie folgt.\n",
        ),
        (
            "Wochenmarkt",
            "2026-11-18 12:10",
            &["alltag"],
            "Äpfel, Kürbis und frisches Brot. Der Stand mit dem Bergkäse hatte wieder die längste Schlange.",
            "",
        ),
        (
            "Synchronisieren mit mehreren Rechnern",
            "2026-11-17 16:55",
            &["meta", "git"],
            "Jeder Rechner schreibt pro Tag eine eigene Transaktionsdatei. Beim Abgleich wird zuerst geholt, dann geschrieben – Konflikte entstehen so kaum.",
            "",
        ),
    ];
    let mut onto = Ontology::default();
    onto.parents.insert("rust".into(), "programmieren".into());
    onto.parents.insert("hugo".into(), "web".into());
    onto.parents.insert("git".into(), "programmieren".into());
    let _ = onto.save(data);
    for (title, date, tags, abs, body) in samples {
        let d = parse_date(date).unwrap();
        let rel_dir = format!("{CONTENT_DIR}/{}/{}", d.format("%Y/%m/%d"), slugify(title, 40));
        let a = Article {
            id: id_from_dir(&rel_dir),
            rel_dir,
            title: title.into(),
            date: d,
            tags: tags.iter().map(|s| s.to_string()).collect(),
            abstract_: abs.into(),
            body: body.into(),
            draft: false,
        };
        let _ = save_article(data, &a);
        let _ = log_tx(data, client, &a, "created");
    }
    let _ = add_snippet(data, "Gefunden: Hugo kann Page Bundles mit Bildern direkt neben index.md.", "Beispiel");
    let _ = add_snippet(data, "> Weniger, aber besser.", "Beispiel");
}

toolUseResult.content:
//! Articles, frontmatter, transaction logs, snippets, tag ontology and settings.
//!
//! Layout of the data folder (it is also the Git repository that gets synced):
//!
//! ```text
//! <data>/content/2026/11/22/<slug>/index.md          one article (Hugo page bundle)
//! <data>/transactions/2026/11/2026-11-22_<client>.json   what changed that day on that client
//! <data>/snippets.json                                snippets collected via right-click
//! <data>/tags.json                                    tag ontology (child -> parent)
//! ```

use chrono::{DateTime, Local, NaiveDateTime, TimeZone};
use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};

pub const CONTENT_DIR: &str = "content";
pub const TX_DIR: &str = "transactions";

// ---------------------------------------------------------------- settings

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(default)]
pub struct Config {
    pub data_dir: PathBuf,
    pub repo_url: String,
    pub branch: String,
    pub client: String,
    /// RFC 3339 time of the last successful sync.
    pub last_sync: Option<String>,
}

impl Default for Config {
    fn default() -> Self {
        let docs = dirs::document_dir()
            .or_else(dirs::home_dir)
            .unwrap_or_else(|| PathBuf::from("."));
        Config {
            data_dir: docs.join("Microblog"),
            repo_url: String::new(),
            branch: "main".into(),
            client: default_client_name(),
            last_sync: None,
        }
    }
}

fn default_client_name() -> String {
    let host = std::env::var("HOSTNAME")
        .ok()
        .or_else(|| {
            std::process::Command::new("hostname")
                .output()
                .ok()
                .map(|o| String::from_utf8_lossy(&o.stdout).trim().to_string())
        })
        .unwrap_or_else(|| "client".into());
    let s = slugify(host.split('.').next().unwrap_or("client"), 24);
    if s.is_empty() {
        "client".into()
    } else {
        s
    }
}

pub fn config_path() -> PathBuf {
    dirs::config_dir()
        .unwrap_or_else(|| PathBuf::from("."))
        .join("Microblog")
        .join("config.json")
}

pub fn load_config() -> Config {
    fs::read_to_string(config_path())
        .ok()
        .and_then(|s| serde_json::from_str(&s).ok())
        .unwrap_or_default()
}

pub fn save_config(cfg: &Config) -> Result<(), String> {
    let p = config_path();
    if let Some(d) = p.parent() {
        fs::create_dir_all(d).map_err(|e| e.to_string())?;
    }
    let s = serde_json::to_string_pretty(cfg).map_err(|e| e.to_string())?;
    fs::write(p, s).map_err(|e| e.to_string())
}

// ---------------------------------------------------------------- articles

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct FrontMatter {
    pub title: String,
    pub date: String,
    pub id: String,
    pub tags: Vec<String>,
    #[serde(rename = "abstract")]
    pub abstract_: String,
    pub draft: bool,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Article {
    pub id: String,
    /// Folder relative to the data folder, e.g. `content/2026/11/22/hallo-welt`.
    pub rel_dir: String,
    pub title: String,
    /// Local time, edited as `YYYY-MM-DD HH:MM`.
    pub date: NaiveDateTime,
    pub tags: Vec<String>,
    pub abstract_: String,
    pub body: String,
    pub draft: bool,
}

impl Article {
    pub fn file(&self, data: &Path) -> PathBuf {
        data.join(&self.rel_dir).join("index.md")
    }

    pub fn to_markdown(&self) -> String {
        let fm = FrontMatter {
            title: self.title.clone(),
            date: format_date_rfc3339(&self.date),
            id: self.id.clone(),
            tags: self.tags.clone(),
            abstract_: self.abstract_.clone(),
            draft: self.draft,
        };
        let yaml = serde_yaml::to_string(&fm).unwrap_or_default();
        let mut out = String::from("---\n");
        out.push_str(&yaml);
        if !yaml.ends_with('\n') {
            out.push('\n');
        }
        out.push_str("---\n\n");
        out.push_str(self.body.trim_end());
        out.push('\n');
        out
    }
}

pub fn format_date_rfc3339(d: &NaiveDateTime) -> String {
    match Local.from_local_datetime(d).single() {
        Some(dt) => dt.to_rfc3339_opts(chrono::SecondsFormat::Secs, false),
        None => d.format("%Y-%m-%dT%H:%M:%S").to_string(),
    }
}

pub fn parse_date(s: &str) -> Option<NaiveDateTime> {
    let s = s.trim();
    if let Ok(dt) = DateTime::parse_from_rfc3339(s) {
        return Some(dt.with_timezone(&Local).naive_local());
    }
    for f in ["%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%dT%H:%M"] {
        if let Ok(d) = NaiveDateTime::parse_from_str(s, f) {
            return Some(d);
        }
    }
    chrono::NaiveDate::parse_from_str(s, "%Y-%m-%d")
        .ok()
        .and_then(|d| d.and_hms_opt(0, 0, 0))
}

pub fn parse_article(text: &str, rel_dir: &str) -> Article {
    let text = text.trim_start_matches('\u{feff}');
    let (fm, body) = split_frontmatter(text);
    let fm: FrontMatter = fm
        .and_then(|y| serde_yaml::from_str(y).ok())
        .unwrap_or_default();
    let date = parse_date(&fm.date)
        .or_else(|| date_from_dir(rel_dir))
        .unwrap_or_else(|| Local::now().naive_local());
    let id = if fm.id.trim().is_empty() {
        id_from_dir(rel_dir)
    } else {
        fm.id.trim().to_string()
    };
    Article {
        id,
        rel_dir: rel_dir.to_string(),
        title: fm.title,
        date,
        tags: normalize_tags(&fm.tags),
        abstract_: fm.abstract_,
        body: body.trim_start_matches('\n').to_string(),
        draft: fm.draft,
    }
}

fn split_frontmatter(text: &str) -> (Option<&str>, &str) {
    let t = text.strip_prefix("---\r\n").or_else(|| text.strip_prefix("---\n"));
    if let Some(rest) = t {
        for marker in ["\n---\n", "\n---\r\n"] {
            if let Some(pos) = rest.find(marker) {
                return (Some(&rest[..pos + 1]), &rest[pos + marker.len()..]);
            }
        }
        if let Some(stripped) = rest.strip_suffix("\n---") {
            return (Some(stripped), "");
        }
    }
    (None, text)
}

/// `content/2026/11/22/slug` -> `2026-11-22-slug`
pub fn id_from_dir(rel_dir: &str) -> String {
    let parts: Vec<&str> = rel_dir.split('/').filter(|p| !p.is_empty()).collect();
    let n = parts.len();
    if n >= 4 {
        format!("{}-{}-{}-{}", parts[n - 4], parts[n - 3], parts[n - 2], parts[n - 1])
    } else {
        parts.join("-")
    }
}

fn date_from_dir(rel_dir: &str) -> Option<NaiveDateTime> {
    let parts: Vec<&str> = rel_dir.split('/').collect();
    let n = parts.len();
    if n < 4 {
        return None;
    }
    let s = format!("{}-{}-{}", parts[n - 4], parts[n - 3], parts[n - 2]);
    parse_date(&s)
}

pub fn normalize_tags(tags: &[String]) -> Vec<String> {
    let mut seen = BTreeSet::new();
    let mut out = Vec::new();
    for t in tags {
        let t = normalize_tag(t);
        if !t.is_empty() && seen.insert(t.clone()) {
            out.push(t);
        }
    }
    out
}

pub fn normalize_tag(t: &str) -> String {
    t.trim()
        .trim_start_matches('#')
        .to_lowercase()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join("-")
}

pub fn slugify(s: &str, max: usize) -> String {
    let mut out = String::new();
    let mut dash = false;
    for c in s.to_lowercase().chars() {
        let rep: &str = match c {
            'ä' => "ae",
            'ö' => "oe",
            'ü' => "ue",
            'ß' => "ss",
            'é' | 'è' | 'ê' => "e",
            'á' | 'à' | 'â' => "a",
            'ó' | 'ò' | 'ô' => "o",
            'í' | 'ì' | 'î' => "i",
            'ú' | 'ù' | 'û' => "u",
            _ => "",
        };
        if !rep.is_empty() {
            out.push_str(rep);
            dash = false;
        } else if c.is_ascii_alphanumeric() {
            out.push(c);
            dash = false;
        } else if !dash && !out.is_empty() {
            out.push('-');
            dash = true;
        }
        if out.len() >= max {
            break;
        }
    }
    out.trim_matches('-').to_string()
}

/// Reads every `index.md` below `content/`.
pub fn load_articles(data: &Path) -> Vec<Article> {
    let mut out = Vec::new();
    let root = data.join(CONTENT_DIR);
    walk(&root, &mut |p| {
        if p.file_name().map(|n| n == "index.md").unwrap_or(false) {
            if let (Ok(text), Some(dir)) = (fs::read_to_string(p), p.parent()) {
                if let Ok(rel) = dir.strip_prefix(data) {
                    let rel = rel.to_string_lossy().replace('\\', "/");
                    out.push(parse_article(&text, &rel));
                }
            }
        }
    });
    out.sort_by(|a, b| b.date.cmp(&a.date).then(b.id.cmp(&a.id)));
    out
}

fn walk(dir: &Path, f: &mut dyn FnMut(&Path)) {
    let Ok(rd) = fs::read_dir(dir) else { return };
    for e in rd.flatten() {
        let p = e.path();
        if p.is_dir() {
            walk(&p, f);
        } else {
            f(&p);
        }
    }
}

/// Creates the folder for a new article, `content/YYYY/MM/DD/<slug>`, unique for that day.
pub fn new_article(data: &Path, title: &str) -> Article {
    let now = Local::now().naive_local();
    let day = now.format("%Y/%m/%d").to_string();
    let mut base = slugify(title, 40);
    if base.is_empty() {
        base = format!("eintrag-{}", now.format("%H%M"));
    }
    let mut slug = base.clone();
    let mut n = 2;
    while data.join(CONTENT_DIR).join(&day).join(&slug).exists() {
        slug = format!("{base}-{n}");
        n += 1;
    }
    let rel_dir = format!("{CONTENT_DIR}/{day}/{slug}");
    Article {
        id: id_from_dir(&rel_dir),
        rel_dir,
        title: title.to_string(),
        date: now,
        tags: vec![],
        abstract_: String::new(),
        body: String::new(),
        draft: false,
    }
}

pub fn save_article(data: &Path, a: &Article) -> Result<(), String> {
    let f = a.file(data);
    if let Some(d) = f.parent() {
        fs::create_dir_all(d).map_err(|e| e.to_string())?;
    }
    fs::write(&f, a.to_markdown()).map_err(|e| e.to_string())
}

pub fn delete_article(data: &Path, a: &Article) -> Result<(), String> {
    let dir = data.join(&a.rel_dir);
    if dir.exists() {
        fs::remove_dir_all(&dir).map_err(|e| e.to_string())?;
    }
    // tidy up empty day/month/year folders
    let mut p = dir.parent().map(|p| p.to_path_buf());
    let stop = data.join(CONTENT_DIR);
    while let Some(d) = p {
        if d == stop || !d.starts_with(&stop) {
            break;
        }
        if fs::remove_dir(&d).is_err() {
            break;
        }
        p = d.parent().map(|p| p.to_path_buf());
    }
    Ok(())
}

// ---------------------------------------------------------------- transactions

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct TxEntry {
    pub time: String,
    pub id: String,
    pub action: String,
    pub path: String,
    #[serde(default)]
    pub title: String,
    #[serde(default)]
    pub client: String,
}

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct TxDay {
    pub date: String,
    pub client: String,
    pub entries: Vec<TxEntry>,
}

fn tx_file(data: &Path, day: &chrono::NaiveDate, client: &str) -> PathBuf {
    data.join(TX_DIR)
        .join(day.format("%Y").to_string())
        .join(day.format("%m").to_string())
        .join(format!("{}_{}.json", day.format("%Y-%m-%d"), client))
}

/// Appends one change to today's transaction file of this client.
/// Several saves of the same article on one day are folded into one entry.
pub fn log_tx(data: &Path, client: &str, a: &Article, action: &str) -> Result<(), String> {
    let now = Local::now();
    let day = now.date_naive();
    let f = tx_file(data, &day, client);
    let mut txd: TxDay = fs::read_to_string(&f)
        .ok()
        .and_then(|s| serde_json::from_str(&s).ok())
        .unwrap_or_default();
    txd.date = day.format("%Y-%m-%d").to_string();
    txd.client = client.to_string();
    let entry = TxEntry {
        time: now.to_rfc3339_opts(chrono::SecondsFormat::Secs, false),
        id: a.id.clone(),
        action: action.to_string(),
        path: format!("{}/index.md", a.rel_dir),
        title: a.title.clone(),
        client: client.to_string(),
    };
    if let Some(last) = txd.entries.iter_mut().rev().find(|e| e.id == a.id) {
        if action == "updated" && (last.action == "updated" || last.action == "created") {
            last.time = entry.time;
            last.title = entry.title;
            write_json(&f, &txd)?;
            return Ok(());
        }
    }
    txd.entries.push(entry);
    write_json(&f, &txd)
}

fn write_json<T: Serialize>(f: &Path, v: &T) -> Result<(), String> {
    if let Some(d) = f.parent() {
        fs::create_dir_all(d).map_err(|e| e.to_string())?;
    }
    let s = serde_json::to_string_pretty(v).map_err(|e| e.to_string())?;
    fs::write(f, s).map_err(|e| e.to_string())
}

/// All transaction entries (from every client) newer than `since`, newest first.
pub fn tx_since(data: &Path, since: Option<&str>) -> Vec<TxEntry> {
    let since = since.and_then(|s| DateTime::parse_from_rfc3339(s).ok());
    let mut out = Vec::new();
    walk(&data.join(TX_DIR), &mut |p| {
        if p.extension().map(|e| e == "json").unwrap_or(false) {
            if let Some(txd) = fs::read_to_string(p)
                .ok()
                .and_then(|s| serde_json::from_str::<TxDay>(&s).ok())
            {
                for mut e in txd.entries {
                    if e.client.is_empty() {
                        e.client = txd.client.clone();
                    }
                    let t = DateTime::parse_from_rfc3339(&e.time).ok();
                    let newer = match (since, t) {
                        (Some(s), Some(t)) => t > s,
                        _ => since.is_none(),
                    };
                    if newer {
                        out.push(e);
                    }
                }
            }
        }
    });
    out.sort_by(|a, b| b.time.cmp(&a.time));
    out
}

// ---------------------------------------------------------------- snippets

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Snippet {
    pub created: String,
    pub text: String,
    #[serde(default)]
    pub source: String,
}

pub fn snippets_path(data: &Path) -> PathBuf {
    data.join("snippets.json")
}

pub fn load_snippets(data: &Path) -> Vec<Snippet> {
    fs::read_to_string(snippets_path(data))
        .ok()
        .and_then(|s| serde_json::from_str(&s).ok())
        .unwrap_or_default()
}

pub fn save_snippets(data: &Path, s: &[Snippet]) -> Result<(), String> {
    write_json(&snippets_path(data), &s)
}

pub fn add_snippet(data: &Path, text: &str, source: &str) -> Result<(), String> {
    let text = text.trim_end();
    if text.trim().is_empty() {
        return Err("leerer Text".into());
    }
    let mut all = load_snippets(data);
    all.insert(
        0,
        Snippet {
            created: Local::now().to_rfc3339_opts(chrono::SecondsFormat::Secs, false),
            text: text.to_string(),
            source: source.to_string(),
        },
    );
    save_snippets(data, &all)
}

// ---------------------------------------------------------------- tag ontology

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct Ontology {
    /// child tag -> parent tag
    pub parents: BTreeMap<String, String>,
}

impl Ontology {
    pub fn load(data: &Path) -> Self {
        fs::read_to_string(data.join("tags.json"))
            .ok()
            .and_then(|s| serde_json::from_str(&s).ok())
            .unwrap_or_default()
    }
    pub fn save(&self, data: &Path) -> Result<(), String> {
        write_json(&data.join("tags.json"), self)
    }
    pub fn parent(&self, t: &str) -> Option<&str> {
        self.parents.get(t).map(|s| s.as_str())
    }
    pub fn children(&self, t: &str) -> Vec<String> {
        self.parents
            .iter()
            .filter(|(_, p)| p.as_str() == t)
            .map(|(c, _)| c.clone())
            .collect()
    }
    /// `t` and everything below it.
    pub fn descendants(&self, t: &str) -> BTreeSet<String> {
        let mut out = BTreeSet::new();
        let mut stack = vec![t.to_string()];
        while let Some(x) = stack.pop() {
            if out.insert(x.clone()) {
                stack.extend(self.children(&x));
            }
        }
        out
    }
    /// Would making `parent` the parent of `child` create a loop?
    pub fn would_cycle(&self, child: &str, parent: &str) -> bool {
        self.descendants(child).contains(parent)
    }
}

// ---------------------------------------------------------------- demo data

/// Writes a few example articles (used for the screenshot when there is no data yet).
pub fn write_demo(data: &Path, client: &str) {
    let samples: [(&str, &str, &[&str], &str, &str); 6] = [
        (
            "Willkommen im Microblog",
            "2026-11-22 09:15",
            &["meta", "notizen"],
            "Kurze Einträge in Markdown schreiben, mit Tags ordnen und per Knopfdruck mit GitHub abgleichen. Jeder Eintrag liegt als eigene Datei im Ordner Content – sortiert nach Jahr, Monat und Tag.",
            "## Schön, dass du da bist\n\nDieser Eintrag zeigt, was **Markdown** kann:\n\n- *kursiv* und **fett**\n- [Links](https://gohugo.io)\n- `Code` im Text\n\n> Ein Zitat sieht so aus.\n\n### Nächste Schritte\n\n1. Oben auf **Neu** klicken\n2. Tags vergeben\n3. Synchronisieren\n",
        ),
        (
            "Hugo-Seite vorbereitet",
            "2026-11-21 18:40",
            &["hugo", "web"],
            "Die Ordnerstruktur passt schon zu Hugo: jeder Eintrag ist ein Page Bundle mit index.md, Frontmatter enthält Titel, Datum, Tags und Abstract.",
            "Die Seite kommt in Stufe 2.\n",
        ),
        (
            "Rust und egui ausprobiert",
            "2026-11-20 21:05",
            &["rust", "programmieren"],
            "Ein kleines Fenster mit Seitenleiste, Liste und Editor. Erstaunlich wenig Code für eine Oberfläche, die sich schnell anfühlt und überall läuft.",
            "```rust\nfn main() {\n    println!(\"Hallo\");\n}\n```\n",
        ),
        (
            "Lesenotiz: Gute Tags",
            "2026-11-19 07:30",
            &["notizen", "lesen"],
            "Tags sind frei vergebbar. Später lassen sie sich ordnen: \"rust\" unter \"programmieren\", \"hugo\" unter \"web\". So bleibt die Seitenleiste übersichtlich und die Suche trotzdem genau.",
            "Ontologie folgt.\n",
        ),
        (
            "Wochenmarkt",
            "2026-11-18 12:10",
            &["alltag"],
            "Äpfel, Kürbis und frisches Brot. Der Stand mit dem Bergkäse hatte wieder die längste Schlange.",
            "",
        ),
        (
            "Synchronisieren mit mehreren Rechnern",
            "2026-11-17 16:55",
            &["meta", "git"],
            "Jeder Rechner schreibt pro Tag eine eigene Transaktionsdatei. Beim Abgleich wird zuerst geholt, dann geschrieben – Konflikte entstehen so kaum.",
            "",
        ),
    ];
    let mut onto = Ontology::default();
    onto.parents.insert("rust".into(), "programmieren".into());
    onto.parents.insert("hugo".into(), "web".into());
    onto.parents.insert("git".into(), "programmieren".into());
    let _ = onto.save(data);
    for (title, date, tags, abs, body) in samples {
        let d = parse_date(date).unwrap();
        let rel_dir = format!("{CONTENT_DIR}/{}/{}", d.format("%Y/%m/%d"), slugify(title, 40));
        let a = Article {
            id: id_from_dir(&rel_dir),
            rel_dir,
            title: title.into(),
            date: d,
            tags: tags.iter().map(|s| s.to_string()).collect(),
            abstract_: abs.into(),
            body: body.into(),
            draft: false,
        };
        let _ = save_article(data, &a);
        let _ = log_tx(data, client, &a, "created");
    }
    let _ = add_snippet(data, "Gefunden: Hugo kann Page Bundles mit Bildern direkt neben index.md.", "Beispiel");
    let _ = add_snippet(data, "> Weniger, aber besser.", "Beispiel");
}

