//! Menu-bar icon (macOS: top right, Windows: notification area) to call up the program at any time.

use std::sync::mpsc::{channel, Receiver};

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum TrayCmd {
    Show,
    New,
    Snippets,
    Sync,
    Quit,
}

pub struct Tray {
    #[cfg(any(target_os = "macos", target_os = "windows"))]
    _icon: tray_icon::TrayIcon,
    pub rx: Receiver<TrayCmd>,
}

/// Draws a small speech-bubble icon (black with transparency, used as a template on macOS).
#[allow(dead_code)]
fn icon_rgba(size: u32) -> Vec<u8> {
    let mut px = vec![0u8; (size * size * 4) as usize];
    let s = size as f32;
    let mut put = |x: i32, y: i32, a: f32| {
        if x >= 0 && y >= 0 && (x as u32) < size && (y as u32) < size {
            let i = ((y as u32 * size + x as u32) * 4) as usize;
            let a = (a.clamp(0.0, 1.0) * 255.0) as u8;
            px[i + 3] = px[i + 3].max(a);
        }
    };
    // rounded rectangle outline
    let (l, t, r, b, rad, w) = (s * 0.08, s * 0.1, s * 0.92, s * 0.72, s * 0.16, s * 0.085);
    for y in 0..size as i32 {
        for x in 0..size as i32 {
            let (fx, fy) = (x as f32 + 0.5, y as f32 + 0.5);
            let cx = fx.clamp(l + rad, r - rad);
            let cy = fy.clamp(t + rad, b - rad);
            let d = ((fx - cx).powi(2) + (fy - cy).powi(2)).sqrt();
            let edge = (rad - d).abs();
            if edge < w / 2.0 + 0.5 {
                put(x, y, w / 2.0 + 0.5 - edge);
            }
            // tail
            let tx = fx - s * 0.22;
            let ty = fy - b;
            if ty >= -1.0 && ty < s * 0.2 && tx >= 0.0 && tx < s * 0.2 - ty {
                put(x, y, 1.0);
            }
            // two text lines
            let in_line = |yy: f32, len: f32| {
                fy > yy - w / 2.0 && fy < yy + w / 2.0 && fx > l + s * 0.17 && fx < l + s * 0.17 + len
            };
            if in_line(s * 0.33, s * 0.5) || in_line(s * 0.5, s * 0.34) {
                put(x, y, 1.0);
            }
        }
    }
    px
}

#[cfg(any(target_os = "macos", target_os = "windows"))]
pub fn create(ctx: egui::Context, ns_view: usize) -> Option<Tray> {
    use tray_icon::menu::{Menu, MenuEvent, MenuItem, PredefinedMenuItem};
    use tray_icon::{Icon, TrayIconBuilder};

    let menu = Menu::new();
    let show = MenuItem::new("Microblog öffnen", true, None);
    let new = MenuItem::new("Neuer Eintrag", true, None);
    let snippets = MenuItem::new("Snippets", true, None);
    let sync = MenuItem::new("Synchronisieren", true, None);
    let quit = MenuItem::new("Beenden", true, None);
    menu.append_items(&[
        &show,
        &new,
        &snippets,
        &PredefinedMenuItem::separator(),
        &sync,
        &PredefinedMenuItem::separator(),
        &quit,
    ])
    .ok()?;
    let ids = [
        (show.id().clone(), TrayCmd::Show),
        (new.id().clone(), TrayCmd::New),
        (snippets.id().clone(), TrayCmd::Snippets),
        (sync.id().clone(), TrayCmd::Sync),
        (quit.id().clone(), TrayCmd::Quit),
    ];
    let size = 44;
    let icon = Icon::from_rgba(icon_rgba(size), size, size).ok()?;
    let tray = TrayIconBuilder::new()
        .with_menu(Box::new(menu))
        .with_tooltip("Microblog")
        .with_icon(icon)
        .with_icon_as_template(true)
        .build()
        .ok()?;

    let (tx, rx) = channel();
    MenuEvent::set_event_handler(Some(move |ev: MenuEvent| {
        if let Some((_, cmd)) = ids.iter().find(|(id, _)| *id == ev.id) {
            // bring the window back first so it gets drawn and can react
            native_show(ns_view);
            ctx.send_viewport_cmd(egui::ViewportCommand::Minimized(false));
            ctx.send_viewport_cmd(egui::ViewportCommand::Visible(true));
            ctx.send_viewport_cmd(egui::ViewportCommand::Focus);
            let _ = tx.send(*cmd);
            ctx.request_repaint();
        }
    }));
    Some(Tray { _icon: tray, rx })
}

#[cfg(not(any(target_os = "macos", target_os = "windows")))]
pub fn create(_ctx: egui::Context, _ns_view: usize) -> Option<Tray> {
    None
}

/// Un-minimises the window and brings the app to the front (macOS).
#[cfg(target_os = "macos")]
pub fn native_show(ns_view: usize) {
    use objc2::runtime::AnyObject;
    use objc2::{class, msg_send};
    unsafe {
        let app: *mut AnyObject = msg_send![class!(NSApplication), sharedApplication];
        if !app.is_null() {
            let _: () = msg_send![app, activateIgnoringOtherApps: true];
        }
        if ns_view != 0 {
            let view = ns_view as *mut AnyObject;
            let win: *mut AnyObject = msg_send![view, window];
            if !win.is_null() {
                let none: *mut AnyObject = std::ptr::null_mut();
                let _: () = msg_send![win, deminiaturize: none];
                let _: () = msg_send![win, makeKeyAndOrderFront: none];
            }
        }
    }
}

#[cfg(not(target_os = "macos"))]
pub fn native_show(_ns_view: usize) {}

