    fn onto_window(&mut self, ctx: &egui::Context) {
        let mut open = true;
        let tags: Vec<String> = self.all_tags().into_iter().collect();
        let mut change: Option<(String, Option<String>)> = None;
        egui::Window::new("Tags ordnen")
            .open(&mut open)
            .default_width(420.0)
            .collapsible(false)
            .show(ctx, |ui| {
                ui.label(
                    RichText::new("Lege für jeden Tag einen Oberbegriff fest. Tags ohne Oberbegriff erscheinen links als Haupttags; die Suche nach einem Oberbegriff findet auch alle Unterbegriffe.")
                        .small()
                        .color(MUTED),
                );
                ui.add_space(6.0);
                egui::ScrollArea::vertical().max_height(420.0).show(ui, |ui| {
                    egui::Grid::new("onto").num_columns(2).striped(true).spacing([16.0, 6.0]).show(ui, |ui| {
                        for t in &tags {
                            ui.label(RichText::new(format!("#{t}")).color(TAGFG));
                            let cur = self.onto.parent(t).map(|s| s.to_string());
                            let label = cur.clone().map(|p| format!("unter #{p}")).unwrap_or_else(|| "— Haupttag —".into());
                            egui::ComboBox::from_id_salt(("parent", t))
                                .selected_text(label)
                                .width(180.0)
                                .show_ui(ui, |ui| {
                                    if ui.selectable_label(cur.is_none(), "— Haupttag —").clicked() {
                                        change = Some((t.clone(), None));
                                    }
                                    for p in &tags {
                                        if p == t || self.onto.would_cycle(t, p) {
                                            continue;
                                        }
                                        if ui.selectable_label(cur.as_deref() == Some(p), format!("#{p}")).clicked() {
                                            change = Some((t.clone(), Some(p.clone())));
                                        }
                                    }
                                });
                            ui.end_row();
                        }
                    });
                });
            });
        if let Some((t, p)) = change {
            match p {
                Some(p) => {
                    self.onto.parents.insert(t, p.clone());
                    self.expanded.insert(p);
                }
                None => {
                    self.onto.parents.remove(&t);
                }
            }
            match self.onto.save(&self.data) {
                Ok(()) => self.set_status("Tag-Ordnung gespeichert.", true),
                Err(e) => self.set_status(format!("Tag-Ordnung nicht gespeichert: {e}"), false),
            }
        }
        self.show_onto = open;
    }

    fn snippets_window(&mut self, ctx: &egui::Context) {
        let mut open = true;
        let mut insert = None;
        let mut remove = None;
        let mut add = false;
        egui::Window::new("Snippets")
            .open(&mut open)
            .default_width(420.0)
            .default_pos(ctx.screen_rect().right_top() + Vec2::new(-460.0, 70.0))
            .collapsible(false)
            .show(ctx, |ui| {
                ui.label(
                    RichText::new("Kleine Textbausteine. Neue kommen über Rechtsklick → Dienste → „Als Microblog-Snippet speichern“ oder hier.")
                        .small()
                        .color(MUTED),
                );
                ui.add(
                    egui::TextEdit::multiline(&mut self.new_snippet)
                        .hint_text("Neues Snippet …")
                        .desired_rows(2)
                        .desired_width(f32::INFINITY),
                );
                if ui.button("➕ Hinzufügen").clicked() {
                    add = true;
                }
                ui.separator();
                egui::ScrollArea::vertical().max_height(360.0).show(ui, |ui| {
                    if self.snippets.is_empty() {
                        ui.label(RichText::new("Noch keine Snippets.").color(MUTED));
                    }
                    for (i, s) in self.snippets.iter().enumerate() {
                        egui::Frame::new()
                            .fill(LISTBG)
                            .stroke(Stroke::new(1.0, LINE))
                            .corner_radius(CornerRadius::same(6))
                            .inner_margin(Margin::same(8))
                            .show(ui, |ui| {
                                ui.set_width(ui.available_width());
                                ui.label(short(&s.text, 220));
                                ui.horizontal(|ui| {
                                    ui.label(
                                        RichText::new(format!("{} · {}", s.source, s.created.get(..16).unwrap_or(&s.created).replace('T', " ")))
                                            .small()
                                            .color(MUTED),
                                    );
                                    ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                                        if ui.small_button("🗑").on_hover_text("Löschen").clicked() {
                                            remove = Some(i);
                                        }
                                        if ui.small_button("Kopieren").clicked() {
                                            ui.ctx().copy_text(s.text.clone());
                                        }
                                        if ui.small_button("Einfügen").clicked() {
                                            insert = Some(s.text.clone());
                                        }
                                    });
                                });
                            });
                        ui.add_space(4.0);
                    }
                });
            });
        if add && !self.new_snippet.trim().is_empty() {
            match store::add_snippet(&self.data, &self.new_snippet, "App") {
                Ok(()) => {
                    self.new_snippet.clear();
                    self.snippets = store::load_snippets(&self.data);
                    self.snippets_mtime = mtime(&store::snippets_path(&self.data));
                }
                Err(e) => self.set_status(format!("Snippet nicht gespeichert: {e}"), false),
            }
        }
        if let Some(i) = remove {
            self.snippets.remove(i);
            let _ = store::save_snippets(&self.data, &self.snippets);
            self.snippets_mtime = mtime(&store::snippets_path(&self.data));
        }
        if let Some(t) = insert {
            self.insert_snippet(ctx, &t);
        }
        self.show_snippets = open;
    }
}

impl eframe::App for MicroblogApp {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        self.handle_tray(ctx);
        self.poll_sync();
        self.watch_files(ctx);
        self.shortcuts(ctx);
        self.close_handling(ctx);
        self.top_bar(ctx);
        self.status_bar(ctx);
        self.tag_panel(ctx);
        self.list_panel(ctx);
        self.editor_panel(ctx);
        self.windows(ctx);
        self.autosave(ctx);
        self.screenshot_step(ctx);
    }

