//! The main window: top bar with tag search, main tags on the left, a scrollable list of
//! 10 entries per page (title + abstract, max. 3 lines) and the Markdown editor with preview.

use crate::service;
use crate::store::{self, Article, Config, Ontology, Snippet, TxEntry};
use crate::sync;
use crate::tray::{self, Tray, TrayCmd};
use eframe::egui::{
    self, Color32, CornerRadius, FontId, Key, Margin, RichText, Sense, Stroke, TextStyle, Vec2,
};
use egui_commonmark::{CommonMarkCache, CommonMarkViewer};
use std::collections::{BTreeMap, BTreeSet};
use std::path::PathBuf;
use std::sync::mpsc::{channel, Receiver};
use std::time::SystemTime;

const PAGE: usize = 10;

const ACCENT: Color32 = Color32::from_rgb(37, 99, 235);
const ACCENT_SOFT: Color32 = Color32::from_rgb(219, 234, 254);
const INK: Color32 = Color32::from_rgb(17, 24, 39);
const MUTED: Color32 = Color32::from_rgb(107, 114, 128);
const LINE: Color32 = Color32::from_rgb(229, 231, 235);
const SIDEBAR: Color32 = Color32::from_rgb(243, 244, 246);
const LISTBG: Color32 = Color32::from_rgb(249, 250, 251);
const TAGBG: Color32 = Color32::from_rgb(238, 242, 255);
const TAGFG: Color32 = Color32::from_rgb(67, 56, 202);
const DANGER: Color32 = Color32::from_rgb(220, 38, 38);
const OK: Color32 = Color32::from_rgb(22, 163, 74);

#[derive(PartialEq, Clone, Copy)]
enum ViewMode {
    Edit,
    Split,
    Preview,
}

struct Editor {
    a: Article,
    saved: Article,
    is_new: bool,
    date_text: String,
    tag_input: String,
    /// selected character range in the body editor
    cursor: Option<(usize, usize)>,
    last_change: f64,
}

impl Editor {
    fn dirty(&self) -> bool {
        if self.is_new {
            !(self.a.title.trim().is_empty()
                && self.a.body.trim().is_empty()
                && self.a.abstract_.trim().is_empty())
        } else {
            self.a != self.saved
        }
    }
}

pub struct MicroblogApp {
    cfg: Config,
    data: PathBuf,
    /// screenshot with example data: never write settings
    demo: bool,
    articles: Vec<Article>,
    onto: Ontology,
    snippets: Vec<Snippet>,
    snippets_mtime: Option<SystemTime>,
    last_watch: f64,

    search: String,
    selected_tag: Option<String>,
    expanded: BTreeSet<String>,
    page: usize,
    filter_key: String,

    editor: Option<Editor>,
    view: ViewMode,
    md_cache: CommonMarkCache,
    focus_body: bool,

    status: String,
    status_ok: bool,
    sync_rx: Option<Receiver<Result<sync::SyncResult, String>>>,
    news: Option<Vec<TxEntry>>,

    show_settings: bool,
    settings_draft: Config,
    show_onto: bool,
    show_snippets: bool,
    new_snippet: String,
    confirm_delete: bool,

    tray: Option<Tray>,
    quitting: bool,
    hint_minimized: bool,

    screenshot: Option<PathBuf>,
    frames: u32,
    shot_requested: bool,
}

impl MicroblogApp {
    pub fn new(cc: &eframe::CreationContext<'_>, screenshot: Option<PathBuf>) -> Self {
        setup_style(&cc.egui_ctx);

        let mut cfg = store::load_config();
        let mut demo = false;
        let mut data = cfg.data_dir.clone();
        if screenshot.is_some() && store::load_articles(&data).is_empty() {
            // show the app with example entries instead of an empty list
            data = std::env::temp_dir().join(format!("microblog-demo-{}", std::process::id()));
            let _ = std::fs::remove_dir_all(&data);
            store::write_demo(&data, &cfg.client);
            cfg.data_dir = data.clone();
            demo = true;
        }

        let tray = if screenshot.is_none() {
            let ns_view = native_view(cc);
            tray::create(cc.egui_ctx.clone(), ns_view)
        } else {
            None
        };

        let mut app = MicroblogApp {
            settings_draft: cfg.clone(),
            cfg,
            data,
            demo,
            articles: vec![],
            onto: Ontology::default(),
            snippets: vec![],
            snippets_mtime: None,
            last_watch: 0.0,
            search: String::new(),
            selected_tag: None,
            expanded: BTreeSet::new(),
            page: 0,
            filter_key: String::new(),
            editor: None,
            view: ViewMode::Split,
            md_cache: CommonMarkCache::default(),
            focus_body: false,
            status: String::new(),
            status_ok: true,
            sync_rx: None,
            news: None,
            show_settings: false,
            show_onto: false,
            show_snippets: false,
            new_snippet: String::new(),
            confirm_delete: false,
            tray,
            quitting: false,
            hint_minimized: false,
            screenshot,
            frames: 0,
            shot_requested: false,
        };
        app.reload();
        app.expanded = app
            .onto
            .parents
            .values()
            .cloned()
            .collect::<BTreeSet<String>>();
        if app.screenshot.is_some() && !app.articles.is_empty() {
            app.open_article(0);
        }
        app.set_status(
            format!("{} Einträge geladen aus {}", app.articles.len(), app.data.display()),
            true,
        );
        app
    }

    // ------------------------------------------------------------ data

    fn reload(&mut self) {
        self.articles = store::load_articles(&self.data);
        self.onto = Ontology::load(&self.data);
        self.snippets = store::load_snippets(&self.data);
        self.snippets_mtime = mtime(&store::snippets_path(&self.data));
        // refresh an open, unchanged article from disk (e.g. after a sync)
        if let Some(ed) = &mut self.editor {
            if !ed.dirty() && !ed.is_new {
                if let Some(a) = self.articles.iter().find(|a| a.id == ed.a.id) {
                    ed.a = a.clone();
                    ed.saved = a.clone();
                    ed.date_text = ed.a.date.format("%Y-%m-%d %H:%M").to_string();
                }
            }
        }
    }

    fn set_status(&mut self, s: impl Into<String>, ok: bool) {
        self.status = s.into();
        self.status_ok = ok;
    }

    fn ancestors(&self, tag: &str) -> Vec<String> {
        let mut out = Vec::new();
        let mut cur = tag.to_string();
        for _ in 0..32 {
            match self.onto.parent(&cur) {
                Some(p) if !out.contains(&p.to_string()) && p != tag => {
                    out.push(p.to_string());
                    cur = p.to_string();
                }
                _ => break,
            }
        }
        out
    }

    /// The article's tags plus all their parent tags.
    fn expanded_tags(&self, a: &Article) -> BTreeSet<String> {
        let mut s = BTreeSet::new();
        for t in &a.tags {
            s.insert(t.clone());
            s.extend(self.ancestors(t));
        }
        s
    }

    fn all_tags(&self) -> BTreeSet<String> {
        let mut s: BTreeSet<String> = self.articles.iter().flat_map(|a| a.tags.clone()).collect();
        for (c, p) in &self.onto.parents {
            s.insert(c.clone());
            s.insert(p.clone());
        }
        s
    }

    fn tag_counts(&self) -> BTreeMap<String, usize> {
        let mut m = BTreeMap::new();
        for a in &self.articles {
            for t in self.expanded_tags(a) {
                *m.entry(t).or_insert(0) += 1;
            }
        }
        m
    }

    fn search_terms(&self) -> Vec<String> {
        self.search
            .split(|c: char| c.is_whitespace() || c == ',')
            .map(store::normalize_tag)
            .filter(|t| !t.is_empty())
            .collect()
    }

    fn filtered(&self) -> Vec<usize> {
        let terms = self.search_terms();
        self.articles
            .iter()
            .enumerate()
            .filter(|(_, a)| {
                let tags = self.expanded_tags(a);
                if let Some(sel) = &self.selected_tag {
                    if !tags.contains(sel) {
                        return false;
                    }
                }
                terms.iter().all(|term| tags.iter().any(|t| t.contains(term.as_str())))
            })
            .map(|(i, _)| i)
            .collect()
    }

    // ------------------------------------------------------------ editing

    fn open_article(&mut self, idx: usize) {
        self.save_current();
        if let Some(a) = self.articles.get(idx).cloned() {
            self.editor = Some(Editor {
                date_text: a.date.format("%Y-%m-%d %H:%M").to_string(),
                saved: a.clone(),
                a,
                is_new: false,
                tag_input: String::new(),
                cursor: None,
                last_change: 0.0,
            });
            self.confirm_delete = false;
        }
    }

    fn open_by_id(&mut self, id: &str) {
        if let Some(i) = self.articles.iter().position(|a| a.id == id) {
            self.open_article(i);
        }
    }

    fn new_entry(&mut self) {
        self.save_current();
        let mut a = store::new_article(&self.data, "");
        if let Some(t) = &self.selected_tag {
            a.tags.push(t.clone());
        }
        self.editor = Some(Editor {
            date_text: a.date.format("%Y-%m-%d %H:%M").to_string(),
            saved: a.clone(),
            a,
            is_new: true,
            tag_input: String::new(),
            cursor: None,
            last_change: 0.0,
        });
        self.confirm_delete = false;
        self.set_status("Neuer Eintrag – Titel eingeben, dann schreiben.", true);
    }

    fn save_current(&mut self) {
        let Some(ed) = &mut self.editor else { return };
        if !ed.dirty() {
            return;
        }
        if ed.is_new {
            // the folder name (and so the ID) comes from the title at the first save
            let fresh = store::new_article(&self.data, &ed.a.title);
            ed.a.rel_dir = fresh.rel_dir;
            ed.a.id = fresh.id;
        }
        ed.a.tags = store::normalize_tags(&ed.a.tags);
        let action = if ed.is_new { "created" } else { "updated" };
        match store::save_article(&self.data, &ed.a) {
            Ok(()) => {
                let _ = store::log_tx(&self.data, &self.cfg.client, &ed.a, action);
                ed.is_new = false;
                ed.saved = ed.a.clone();
                let a = ed.a.clone();
                if let Some(slot) = self.articles.iter_mut().find(|x| x.id == a.id) {
                    *slot = a.clone();
                } else {
                    self.articles.push(a.clone());
                }
                self.articles
                    .sort_by(|x, y| y.date.cmp(&x.date).then(y.id.cmp(&x.id)));
                self.set_status(format!("Gespeichert: {}", a.id), true);
            }
            Err(e) => self.set_status(format!("Speichern fehlgeschlagen: {e}"), false),
        }
    }

    fn delete_current(&mut self) {
        let Some(ed) = self.editor.take() else { return };
        if ed.is_new {
            self.set_status("Entwurf verworfen.", true);
            return;
        }
        match store::delete_article(&self.data, &ed.saved) {
            Ok(()) => {
                let _ = store::log_tx(&self.data, &self.cfg.client, &ed.saved, "deleted");
                self.articles.retain(|a| a.id != ed.saved.id);
                self.set_status(format!("Gelöscht: {}", ed.saved.id), true);
            }
            Err(e) => {
                self.set_status(format!("Löschen fehlgeschlagen: {e}"), false);
                self.editor = Some(ed);
            }
        }
    }

    /// Wraps the current selection in the body with `before`/`after`
    /// (or inserts `placeholder` between them when nothing is selected).
    fn insert_text(&mut self, ctx: &egui::Context, before: &str, after: &str, placeholder: &str) {
        let Some(ed) = &mut self.editor else { return };
        let body = &ed.a.body;
        let n = body.chars().count();
        let (s, e) = ed.cursor.unwrap_or((n, n));
        let (s, e) = (s.min(n), e.min(n));
        let (s, e) = (s.min(e), s.max(e));
        let bs = byte_idx(body, s);
        let be = byte_idx(body, e);
        let selected = &body[bs..be];
        let inner = if selected.is_empty() { placeholder } else { selected };
        let new_body = format!("{}{}{}{}{}", &body[..bs], before, inner, after, &body[be..]);
        let sel_start = s + before.chars().count();
        let sel_end = sel_start + inner.chars().count();
        ed.a.body = new_body;
        ed.cursor = Some((sel_start, sel_end));
        ed.last_change = ctx.input(|i| i.time);
        set_body_cursor(ctx, sel_start, sel_end);
        self.focus_body = true;
    }

    /// Puts `prefix` at the start of the line where the cursor is.
    fn insert_line_prefix(&mut self, ctx: &egui::Context, prefix: &str) {
        let Some(ed) = &mut self.editor else { return };
        let body = &ed.a.body;
        let n = body.chars().count();
        let (s, _) = ed.cursor.unwrap_or((n, n));
        let s = s.min(n);
        let bs = byte_idx(body, s);
        let line_start_b = body[..bs].rfind('\n').map(|p| p + 1).unwrap_or(0);
        let new_body = format!("{}{}{}", &body[..line_start_b], prefix, &body[line_start_b..]);
        let c = s + prefix.chars().count();
        ed.a.body = new_body;
        ed.cursor = Some((c, c));
        ed.last_change = ctx.input(|i| i.time);
        set_body_cursor(ctx, c, c);
        self.focus_body = true;
    }

    fn insert_snippet(&mut self, ctx: &egui::Context, text: &str) {
        if self.editor.is_none() {
            self.new_entry();
        }
        let t = format!("{text}\n");
        self.insert_text(ctx, &t, "", "");
        self.set_status("Snippet eingefügt.", true);
    }

    // ------------------------------------------------------------ sync

    fn start_sync(&mut self, ctx: &egui::Context) {
        if self.sync_rx.is_some() {
            return;
        }
        if self.demo {
            self.set_status("Beispieldaten werden nicht synchronisiert.", false);
            return;
        }
        self.save_current();
        let (tx, rx) = channel();
        let data = self.data.clone();
        let url = self.cfg.repo_url.clone();
        let branch = self.cfg.branch.clone();
        let client = self.cfg.client.clone();
        let ctx2 = ctx.clone();
        std::thread::spawn(move || {
            let r = sync::sync(&data, &url, &branch, &client);
            let _ = tx.send(r);
            ctx2.request_repaint();
        });
        self.sync_rx = Some(rx);
        self.set_status("Synchronisiere mit GitHub …", true);
    }

    fn poll_sync(&mut self) {
        let Some(rx) = &self.sync_rx else { return };
        let Ok(res) = rx.try_recv() else { return };
        self.sync_rx = None;
        match res {
            Ok(r) => {
                self.reload();
                let mut news: Vec<TxEntry> = store::tx_since(&self.data, self.cfg.last_sync.as_deref())
                    .into_iter()
                    .filter(|e| e.client != self.cfg.client)
                    .collect();
                news.truncate(200);
                self.cfg.last_sync = Some(
                    chrono::Local::now().to_rfc3339_opts(chrono::SecondsFormat::Secs, false),
                );
                if !self.demo {
                    let _ = store::save_config(&self.cfg);
                }
                self.set_status(format!("Synchronisiert. {}", r.log.join(" ")), true);
                self.news = Some(news);
            }
            Err(e) => self.set_status(format!("Synchronisieren fehlgeschlagen: {e}"), false),
        }
    }

    fn apply_settings(&mut self) {
        self.save_current();
        let changed_dir = self.settings_draft.data_dir != self.cfg.data_dir;
        self.settings_draft.client = {
            let c = store::slugify(&self.settings_draft.client, 24);
            if c.is_empty() { "client".into() } else { c }
        };
        self.cfg = self.settings_draft.clone();
        if changed_dir {
            self.data = self.cfg.data_dir.clone();
            self.demo = false;
            self.editor = None;
            self.reload();
        }
        match store::save_config(&self.cfg) {
            Ok(()) => self.set_status("Einstellungen gespeichert.", true),
            Err(e) => self.set_status(format!("Einstellungen nicht gespeichert: {e}"), false),
        }
    }

    // ------------------------------------------------------------ frame helpers

    fn handle_tray(&mut self, ctx: &egui::Context) {
        let cmds: Vec<TrayCmd> = match &self.tray {
            Some(t) => t.rx.try_iter().collect(),
            None => return,
        };
        for c in cmds {
            match c {
                TrayCmd::Show => {}
                TrayCmd::New => self.new_entry(),
                TrayCmd::Snippets => self.show_snippets = true,
                TrayCmd::Sync => self.start_sync(ctx),
                TrayCmd::Quit => {
                    self.save_current();
                    self.quitting = true;
                    ctx.send_viewport_cmd(egui::ViewportCommand::Close);
                }
            }
        }
    }

    fn watch_files(&mut self, ctx: &egui::Context) {
        let now = ctx.input(|i| i.time);
        if now - self.last_watch < 1.0 {
            return;
        }
        self.last_watch = now;
        let m = mtime(&store::snippets_path(&self.data));
        if m != self.snippets_mtime {
            self.snippets_mtime = m;
            let before = self.snippets.len();
            self.snippets = store::load_snippets(&self.data);
            if self.snippets.len() > before {
                self.set_status("Neues Snippet empfangen.", true);
            }
        }
        ctx.request_repaint_after(std::time::Duration::from_secs(1));
    }

    fn shortcuts(&mut self, ctx: &egui::Context) {
        let (save, new) = ctx.input_mut(|i| {
            (
                i.consume_key(egui::Modifiers::COMMAND, Key::S),
                i.consume_key(egui::Modifiers::COMMAND, Key::N),
            )
        });
        if save {
            self.save_current();
        }
        if new {
            self.new_entry();
        }
    }

    fn close_handling(&mut self, ctx: &egui::Context) {
        if ctx.input(|i| i.viewport().close_requested()) {
            self.save_current();
            if self.tray.is_some() && !self.quitting {
                // keep running in the menu bar
                ctx.send_viewport_cmd(egui::ViewportCommand::CancelClose);
                ctx.send_viewport_cmd(egui::ViewportCommand::Minimized(true));
                if !self.hint_minimized {
                    self.hint_minimized = true;
                    self.set_status(
                        "Microblog läuft weiter – über das Symbol in der Menüleiste wieder öffnen oder beenden.",
                        true,
                    );
                }
            }
        }
    }

    fn autosave(&mut self, ctx: &egui::Context) {
        let now = ctx.input(|i| i.time);
        let due = match &self.editor {
            Some(ed) if ed.dirty() => {
                ctx.request_repaint_after(std::time::Duration::from_millis(500));
                now - ed.last_change > 1.5 && !ed.a.title.trim().is_empty()
            }
            _ => false,
        };
        if due {
            self.save_current();
        }
    }

    fn screenshot_step(&mut self, ctx: &egui::Context) {
        let Some(path) = self.screenshot.clone() else { return };
        self.frames += 1;
        ctx.request_repaint();
        if self.frames >= 120 && !self.shot_requested {
            self.shot_requested = true;
            ctx.send_viewport_cmd(egui::ViewportCommand::Screenshot(egui::UserData::default()));
        }
        let shot = ctx.input(|i| {
            i.events.iter().find_map(|e| match e {
                egui::Event::Screenshot { image, .. } => Some(image.clone()),
                _ => None,
            })
        });
        if let Some(img) = shot {
            let [w, h] = img.size;
            let bytes: Vec<u8> = img.pixels.iter().flat_map(|c| c.to_array()).collect();
            if let Some(d) = path.parent() {
                let _ = std::fs::create_dir_all(d);
            }
            match image::save_buffer(&path, &bytes, w as u32, h as u32, image::ColorType::Rgba8) {
                Ok(()) => println!("Screenshot gespeichert: {}", path.display()),
                Err(e) => eprintln!("Screenshot fehlgeschlagen: {e}"),
            }
            if self.demo {
                let _ = std::fs::remove_dir_all(&self.data);
            }
            std::process::exit(0);
        }
        if self.frames > 600 {
            eprintln!("Screenshot kam nicht an");
            std::process::exit(1);
        }
    }

    // ------------------------------------------------------------ UI: top bar

    fn top_bar(&mut self, ctx: &egui::Context) {
        egui::TopBottomPanel::top("top")
            .frame(
                egui::Frame::new()
                    .fill(Color32::WHITE)
                    .inner_margin(Margin::symmetric(14, 10))
                    .stroke(Stroke::new(1.0, LINE)),
            )
            .show(ctx, |ui| {
                ui.horizontal(|ui| {
                    // logo
                    let (r, p) = ui.allocate_painter(Vec2::splat(28.0), Sense::hover());
                    let rect = r.rect;
                    p.rect_filled(rect, CornerRadius::same(7), ACCENT);
                    p.text(
                        rect.center(),
                        egui::Align2::CENTER_CENTER,
                        "µ",
                        FontId::proportional(19.0),
                        Color32::WHITE,
                    );
                    ui.label(RichText::new("Microblog").size(18.0).strong().color(INK));
                    ui.add_space(24.0);

                    let search = ui.add(
                        egui::TextEdit::singleline(&mut self.search)
                            .hint_text("🔍  Nach Tags suchen …  (z. B. rust web)")
                            .desired_width(360.0)
                            .margin(Margin::symmetric(8, 5)),
                    );
                    if search.changed() {
                        self.page = 0;
                    }
                    if !self.search.is_empty() && ui.small_button("✖").on_hover_text("Suche leeren").clicked() {
                        self.search.clear();
                    }

                    ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                        if ui
                            .add(egui::Button::new(RichText::new("⚙").size(16.0)).frame(false))
                            .on_hover_text("Einstellungen")
                            .clicked()
                        {
                            self.settings_draft = self.cfg.clone();
                            self.show_settings = true;
                        }
                        let syncing = self.sync_rx.is_some();
                        let label = if syncing { "Synchronisiere …" } else { "🔄  Synchronisieren" };
                        if ui
                            .add_enabled(!syncing, egui::Button::new(label))
                            .on_hover_text("Neues aus dem GitHub-Repository holen und eigene Einträge hineinschreiben")
                            .clicked()
                        {
                            self.start_sync(ctx);
                        }
                        if syncing {
                            ui.spinner();
                        }
                        if ui
                            .add(egui::Button::new(RichText::new("📋  Snippets").color(INK)))
                            .clicked()
                        {
                            self.show_snippets = !self.show_snippets;
                        }
                        if ui
                            .add(
                                egui::Button::new(RichText::new("➕  Neu").color(Color32::WHITE).strong())
                                    .fill(ACCENT),
                            )
                            .on_hover_text("Neuer Eintrag (⌘N)")
                            .clicked()
                        {
                            self.new_entry();
                        }
                    });
                });
            });
    }

    fn status_bar(&mut self, ctx: &egui::Context) {
        egui::TopBottomPanel::bottom("status")
            .frame(
                egui::Frame::new()
                    .fill(Color32::WHITE)
                    .inner_margin(Margin::symmetric(12, 5))
                    .stroke(Stroke::new(1.0, LINE)),
            )
            .show(ctx, |ui| {
                ui.horizontal(|ui| {
                    let c = if self.status_ok { MUTED } else { DANGER };
                    ui.label(RichText::new(&self.status).small().color(c));
                    ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                        let last = self
                            .cfg
                            .last_sync
                            .as_deref()
                            .and_then(|s| chrono::DateTime::parse_from_rfc3339(s).ok())
                            .map(|d| d.format("%d.%m.%Y %H:%M").to_string())
                            .unwrap_or_else(|| "noch nie".into());
                        ui.label(RichText::new(format!("Zuletzt synchronisiert: {last}")).small().color(MUTED));
                        ui.label(RichText::new("·").small().color(MUTED));
                        ui.label(
                            RichText::new(format!("Rechner: {}", self.cfg.client))
                                .small()
                                .color(MUTED),
                        );
                    });
                });
            });
    }

    // ------------------------------------------------------------ UI: tag sidebar

    fn tag_panel(&mut self, ctx: &egui::Context) {
        let counts = self.tag_counts();
        let mut roots: Vec<String> = self
            .all_tags()
            .into_iter()
            .filter(|t| self.onto.parent(t).is_none())
            .collect();
        roots.sort_by(|a, b| {
            counts
                .get(b)
                .unwrap_or(&0)
                .cmp(counts.get(a).unwrap_or(&0))
                .then(a.cmp(b))
        });

        egui::SidePanel::left("tags")
            .resizable(false)
            .exact_width(200.0)
            .frame(
                egui::Frame::new()
                    .fill(SIDEBAR)
                    .inner_margin(Margin::symmetric(10, 12))
                    .stroke(Stroke::new(1.0, LINE)),
            )
            .show(ctx, |ui| {
                ui.label(RichText::new("HAUPTTAGS").small().strong().color(MUTED));
                ui.add_space(6.0);
                let all_sel = self.selected_tag.is_none();
                if tag_row(ui, "Alle Einträge", self.articles.len(), all_sel, 0, None).0 {
                    self.selected_tag = None;
                    self.page = 0;
                }
                ui.add_space(4.0);
                egui::ScrollArea::vertical()
                    .id_salt("tagscroll")
                    .auto_shrink([false, false])
                    .max_height(ui.available_height() - 70.0)
                    .show(ui, |ui| {
                        for t in &roots {
                            self.tag_tree(ui, t, 0, &counts);
                        }
                        if roots.is_empty() {
                            ui.label(RichText::new("Noch keine Tags.").small().color(MUTED));
                        }
                    });
                ui.with_layout(egui::Layout::bottom_up(egui::Align::Min), |ui| {
                    if ui
                        .add(egui::Button::new(RichText::new("🗂  Tags ordnen …").color(INK)).frame(false))
                        .on_hover_text("Über- und Unterbegriffe der Tags festlegen")
                        .clicked()
                    {
                        self.show_onto = true;
                    }
                    ui.separator();
                });
            });
    }

    fn tag_tree(&mut self, ui: &mut egui::Ui, tag: &str, depth: usize, counts: &BTreeMap<String, usize>) {
        let mut children = self.onto.children(tag);
        children.sort();
        let has_children = !children.is_empty();
        let open = self.expanded.contains(tag);
        let sel = self.selected_tag.as_deref() == Some(tag);
        let (clicked, toggled) = tag_row(
            ui,
            &format!("#{tag}"),
            *counts.get(tag).unwrap_or(&0),
            sel,
            depth,
            if has_children { Some(open) } else { None },
        );
        if clicked {
            self.selected_tag = if sel { None } else { Some(tag.to_string()) };
            self.page = 0;
        }
        if toggled {
            if open {
                self.expanded.remove(tag);
            } else {
                self.expanded.insert(tag.to_string());
            }
        }
        if open && depth < 8 {
            for c in children {
                self.tag_tree(ui, &c, depth + 1, counts);
            }
        }
    }

    // ------------------------------------------------------------ UI: list

    fn list_panel(&mut self, ctx: &egui::Context) {
        let items = self.filtered();
        let key = format!("{:?}|{}", self.selected_tag, self.search);
        if key != self.filter_key {
            self.filter_key = key;
            self.page = 0;
        }
        let pages = items.len().div_ceil(PAGE).max(1);
        self.page = self.page.min(pages - 1);
        let current_id = self.editor.as_ref().map(|e| e.a.id.clone());

        egui::SidePanel::left("list")
            .resizable(true)
            .default_width(400.0)
            .width_range(320.0..=560.0)
            .frame(
                egui::Frame::new()
                    .fill(LISTBG)
                    .inner_margin(Margin::symmetric(12, 12))
                    .stroke(Stroke::new(1.0, LINE)),
            )
            .show(ctx, |ui| {
                // header
                ui.horizontal(|ui| {
                    let title = match &self.selected_tag {
                        Some(t) => format!("#{t}"),
                        None => "Alle Einträge".into(),
                    };
                    ui.label(RichText::new(title).size(16.0).strong().color(INK));
                    ui.label(RichText::new(format!("{} Treffer", items.len())).small().color(MUTED));
                });
                // matching tags for the search
                let terms = self.search_terms();
                if !terms.is_empty() {
                    let matches: Vec<String> = self
                        .all_tags()
                        .into_iter()
                        .filter(|t| terms.iter().any(|q| t.contains(q.as_str())))
                        .take(8)
                        .collect();
                    ui.horizontal_wrapped(|ui| {
                        ui.label(RichText::new("Passende Tags:").small().color(MUTED));
                        for t in matches {
                            if tag_chip(ui, &t).clicked() {
                                self.selected_tag = Some(t.clone());
                                self.search.clear();
                            }
                        }
                    });
                }
                ui.add_space(6.0);

                let footer_h = 34.0;
                egui::ScrollArea::vertical()
                    .id_salt(("listscroll", self.page, self.filter_key.clone()))
                    .auto_shrink([false, false])
                    .max_height(ui.available_height() - footer_h)
                    .show(ui, |ui| {
                        if items.is_empty() {
                            ui.add_space(30.0);
                            ui.vertical_centered(|ui| {
                                if self.articles.is_empty() {
                                    ui.label(RichText::new("Noch keine Einträge").size(15.0).color(INK));
                                    ui.label(RichText::new("Klicke oben auf „➕ Neu“, um den ersten Microblog zu schreiben.").color(MUTED));
                                    ui.add_space(8.0);
                                    if ui.button("Beispieleinträge anlegen").clicked() {
                                        store::write_demo(&self.data, &self.cfg.client);
                                        self.reload();
                                    }
                                } else {
                                    ui.label(RichText::new("Keine Einträge mit diesen Tags.").color(MUTED));
                                }
                            });
                        }
                        let start = self.page * PAGE;
                        let mut open = None;
                        let mut chip = None;
                        for &i in items.iter().skip(start).take(PAGE) {
                            let a = &self.articles[i];
                            let sel = current_id.as_deref() == Some(a.id.as_str());
                            let (c, t) = entry_card(ui, a, sel);
                            if c {
                                open = Some(i);
                            }
                            if t.is_some() {
                                chip = t;
                            }
                            ui.add_space(8.0);
                        }
                        if let Some(t) = chip {
                            self.selected_tag = Some(t);
                        } else if let Some(i) = open {
                            self.open_article(i);
                        }
                    });

                // pager
                ui.add_space(4.0);
                ui.horizontal(|ui| {
                    if ui.add_enabled(self.page > 0, egui::Button::new("‹ Neuere")).clicked() {
                        self.page -= 1;
                    }
                    ui.label(
                        RichText::new(format!("Seite {} von {}", self.page + 1, pages))
                            .small()
                            .color(MUTED),
                    );
                    if ui
                        .add_enabled(self.page + 1 < pages, egui::Button::new("Ältere ›"))
                        .clicked()
                    {
                        self.page += 1;
                    }
                });
            });
    }

    // ------------------------------------------------------------ UI: editor

    fn editor_panel(&mut self, ctx: &egui::Context) {
        egui::CentralPanel::default()
            .frame(
                egui::Frame::new()
                    .fill(Color32::WHITE)
                    .inner_margin(Margin::symmetric(18, 14)),
            )
            .show(ctx, |ui| {
                if self.editor.is_none() {
                    ui.add_space(ui.available_height() * 0.35);
                    ui.vertical_centered(|ui| {
                        ui.label(RichText::new("Kein Eintrag geöffnet").size(18.0).color(INK));
                        ui.label(RichText::new("Wähle links einen Eintrag oder lege einen neuen an.").color(MUTED));
                        ui.add_space(10.0);
                        if ui
                            .add(egui::Button::new(RichText::new("➕  Neuer Eintrag").color(Color32::WHITE)).fill(ACCENT))
                            .clicked()
                        {
                            self.new_entry();
                        }
                    });
                    return;
                }
                self.editor_ui(ui, ctx);
            });
    }

    fn editor_ui(&mut self, ui: &mut egui::Ui, ctx: &egui::Context) {
        let now = ctx.input(|i| i.time);
        let all_tags = self.all_tags();
        let snippets = self.snippets.clone();
        let mut changed = false;
        let mut action_save = false;
        let mut action_delete = false;
        let mut fmt: Option<(&'static str, &'static str, &'static str)> = None;
        let mut prefix: Option<&'static str> = None;
        let mut snippet_insert: Option<String> = None;

        // bottom bar of the editor
        egui::TopBottomPanel::bottom("editor_bottom")
            .frame(egui::Frame::new().inner_margin(Margin { left: 0, right: 0, top: 8, bottom: 0 }))
            .show_separator_line(false)
            .show_inside(ui, |ui| {
                let ed = self.editor.as_ref().unwrap();
                ui.horizontal(|ui| {
                    if ui
                        .add(egui::Button::new(RichText::new("💾  Speichern").color(Color32::WHITE)).fill(ACCENT))
                        .on_hover_text("⌘S – wird auch automatisch gespeichert")
                        .clicked()
                    {
                        action_save = true;
                    }
                    if ui.button(RichText::new("🗑  Löschen").color(DANGER)).clicked() {
                        action_delete = true;
                    }
                    if ed.dirty() {
                        ui.label(RichText::new("● Ungespeichert").small().color(Color32::from_rgb(217, 119, 6)));
                    } else {
                        ui.label(RichText::new("✔ Gespeichert").small().color(OK));
                    }
                    ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                        let path = if ed.is_new {
                            "Ordner wird beim ersten Speichern angelegt".to_string()
                        } else {
                            format!("{}/index.md", ed.a.rel_dir)
                        };
                        ui.label(RichText::new(path).small().monospace().color(MUTED));
                    });
                });
            });

        let ed = self.editor.as_mut().unwrap();

        // title
        let r = ui.add(
            egui::TextEdit::singleline(&mut ed.a.title)
                .hint_text("Titel")
                .font(FontId::proportional(22.0))
                .frame(false)
                .desired_width(f32::INFINITY),
        );
        changed |= r.changed();
        ui.add(egui::Separator::default().spacing(6.0));

        // frontmatter: date, id, draft
        egui::Grid::new("fm")
            .num_columns(2)
            .spacing([12.0, 8.0])
            .show(ui, |ui| {
                ui.label(RichText::new("Datum").color(MUTED));
                ui.horizontal(|ui| {
                    let valid = store::parse_date(&ed.date_text).is_some();
                    let r = ui.add(
                        egui::TextEdit::singleline(&mut ed.date_text)
                            .desired_width(140.0)
                            .text_color(if valid { INK } else { DANGER })
                            .hint_text("JJJJ-MM-TT HH:MM"),
                    );
                    if r.changed() {
                        if let Some(d) = store::parse_date(&ed.date_text) {
                            ed.a.date = d;
                            changed = true;
                        }
                    }
                    if ui.small_button("Jetzt").clicked() {
                        ed.a.date = chrono::Local::now().naive_local();
                        ed.date_text = ed.a.date.format("%Y-%m-%d %H:%M").to_string();
                        changed = true;
                    }
                    ui.add_space(12.0);
                    changed |= ui.checkbox(&mut ed.a.draft, "Entwurf").changed();
                    ui.add_space(12.0);
                    let id = if ed.is_new { "ID: (neu)".to_string() } else { format!("ID: {}", ed.a.id) };
                    ui.label(RichText::new(id).small().monospace().color(MUTED));
                });
                ui.end_row();

                ui.label(RichText::new("Tags").color(MUTED));
                ui.horizontal_wrapped(|ui| {
                    let mut remove = None;
                    for (i, t) in ed.a.tags.iter().enumerate() {
                        let b = egui::Button::new(RichText::new(format!("#{t}  ✖")).small().color(TAGFG))
                            .fill(TAGBG)
                            .corner_radius(CornerRadius::same(9));
                        if ui.add(b).on_hover_text("Tag entfernen").clicked() {
                            remove = Some(i);
                        }
                    }
                    if let Some(i) = remove {
                        ed.a.tags.remove(i);
                        changed = true;
                    }
                    let r = ui.add(
                        egui::TextEdit::singleline(&mut ed.tag_input)
                            .hint_text("Tag hinzufügen …")
                            .desired_width(130.0),
                    );
                    let enter = r.lost_focus() && ui.input(|i| i.key_pressed(Key::Enter));
                    if enter || ed.tag_input.ends_with(',') {
                        for t in ed.tag_input.split(',') {
                            let t = store::normalize_tag(t);
                            if !t.is_empty() && !ed.a.tags.contains(&t) {
                                ed.a.tags.push(t);
                                changed = true;
                            }
                        }
                        ed.tag_input.clear();
                        if enter {
                            r.request_focus();
                        }
                    }
                    // suggestions
                    let q = store::normalize_tag(&ed.tag_input);
                    if !q.is_empty() {
                        for t in all_tags
                            .iter()
                            .filter(|t| t.contains(q.as_str()) && !ed.a.tags.contains(t))
                            .take(5)
                        {
                            if ui
                                .add(egui::Button::new(RichText::new(format!("+ #{t}")).small().color(MUTED)).frame(false))
                                .clicked()
                            {
                                ed.a.tags.push(t.clone());
                                ed.tag_input.clear();
                                changed = true;
                            }
                        }
                    }
                });
                ui.end_row();
            });

        ui.add_space(6.0);
        ui.horizontal(|ui| {
            ui.label(RichText::new("Abstract").color(MUTED));
            ui.label(RichText::new("– erscheint in der Liste (höchstens 3 Zeilen)").small().color(MUTED));
        });
        let r = ui.add(
            egui::TextEdit::multiline(&mut ed.a.abstract_)
                .hint_text("Kurze Zusammenfassung …")
                .desired_rows(2)
                .desired_width(f32::INFINITY),
        );
        changed |= r.changed();
        ui.add_space(8.0);

        // toolbar
        ui.horizontal(|ui| {
            ui.spacing_mut().item_spacing.x = 4.0;
            let tb = |ui: &mut egui::Ui, label: RichText, tip: &str| -> bool {
                ui.add(egui::Button::new(label).min_size(Vec2::new(30.0, 24.0)))
                    .on_hover_text(tip)
                    .clicked()
            };
            if tb(ui, RichText::new("B").strong(), "Fett") {
                fmt = Some(("**", "**", "fett"));
            }
            if tb(ui, RichText::new("I").italics(), "Kursiv") {
                fmt = Some(("*", "*", "kursiv"));
            }
            if tb(ui, RichText::new("S").strikethrough(), "Durchgestrichen") {
                fmt = Some(("~~", "~~", "Text"));
            }
            if tb(ui, RichText::new("H2"), "Überschrift") {
                prefix = Some("## ");
            }
            if tb(ui, RichText::new("•"), "Liste") {
                prefix = Some("- ");
            }
            if tb(ui, RichText::new("1."), "Nummerierte Liste") {
                prefix = Some("1. ");
            }
            if tb(ui, RichText::new("❝"), "Zitat") {
                prefix = Some("> ");
            }
            if tb(ui, RichText::new("</>").monospace(), "Code") {
                fmt = Some(("`", "`", "code"));
            }
            if tb(ui, RichText::new("🔗"), "Link") {
                fmt = Some(("[", "](https://)", "Linktext"));
            }
            ui.add_space(6.0);
            ui.menu_button("📋 Snippet ▾", |ui| {
                if snippets.is_empty() {
                    ui.label(RichText::new("Noch keine Snippets").color(MUTED));
                }
                for s in snippets.iter().take(15) {
                    if ui.button(short(&s.text, 48)).clicked() {
                        snippet_insert = Some(s.text.clone());
                        ui.close_menu();
                    }
                }
            });
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                ui.selectable_value(&mut self.view, ViewMode::Preview, "Vorschau");
                ui.selectable_value(&mut self.view, ViewMode::Split, "Geteilt");
                ui.selectable_value(&mut self.view, ViewMode::Edit, "Bearbeiten");
            });
        });
        ui.add_space(4.0);

        // body editor + preview
        let ed = self.editor.as_mut().unwrap();
        let view = self.view;
        let h = ui.available_height();
        let body_id = egui::Id::new("body_editor");
        let preview_md = format!(
            "# {}\n\n{}\n\n---\n\n{}",
            if ed.a.title.trim().is_empty() { "Ohne Titel" } else { ed.a.title.trim() },
            if ed.a.abstract_.trim().is_empty() {
                String::new()
            } else {
                format!("*{}*", ed.a.abstract_.trim().replace('\n', " "))
            },
            ed.a.body
        );
        let md_cache = &mut self.md_cache;
        let focus_body = std::mem::take(&mut self.focus_body);

        let mut body_editor = |ui: &mut egui::Ui, ed: &mut Editor| {
            egui::Frame::new()
                .fill(Color32::from_rgb(252, 252, 253))
                .stroke(Stroke::new(1.0, LINE))
                .corner_radius(CornerRadius::same(6))
                .inner_margin(Margin::same(6))
                .show(ui, |ui| {
                    egui::ScrollArea::vertical()
                        .id_salt("bodyscroll")
                        .auto_shrink([false, false])
                        .max_height(h - 14.0)
                        .show(ui, |ui| {
                            let out = egui::TextEdit::multiline(&mut ed.a.body)
                                .id(body_id)
                                .font(TextStyle::Monospace)
                                .hint_text("Artikel in Markdown schreiben …  (Rechtsklick: Snippets & Formatierung)")
                                .frame(false)
                                .desired_width(f32::INFINITY)
                                .min_size(Vec2::new(0.0, h - 28.0))
                                .show(ui);
                            if let Some(cr) = out.cursor_range {
                                ed.cursor = Some((cr.primary.index.min(cr.secondary.index), cr.primary.index.max(cr.secondary.index)));
                            }
                            if focus_body {
                                out.response.request_focus();
                            }
                            if out.response.changed() {
                                changed = true;
                            }
                            out.response.context_menu(|ui| {
                                ui.label(RichText::new("Snippet einfügen").small().strong().color(MUTED));
                                if snippets.is_empty() {
                                    ui.label(RichText::new("Noch keine Snippets").color(MUTED));
                                }
                                for s in snippets.iter().take(12) {
                                    if ui.button(short(&s.text, 48)).clicked() {
                                        snippet_insert = Some(s.text.clone());
                                        ui.close_menu();
                                    }
                                }
                                ui.separator();
                                ui.label(RichText::new("Formatieren").small().strong().color(MUTED));
                                if ui.button("Fett").clicked() {
                                    fmt = Some(("**", "**", "fett"));
                                    ui.close_menu();
                                }
                                if ui.button("Kursiv").clicked() {
                                    fmt = Some(("*", "*", "kursiv"));
                                    ui.close_menu();
                                }
                                if ui.button("Link").clicked() {
                                    fmt = Some(("[", "](https://)", "Linktext"));
                                    ui.close_menu();
                                }
                                if ui.button("Überschrift").clicked() {
                                    prefix = Some("## ");
                                    ui.close_menu();
                                }
                                if ui.button("Zitat").clicked() {
                                    prefix = Some("> ");
                                    ui.close_menu();
                                }
                            });
                        });
                });
        };
        let preview = |ui: &mut egui::Ui, cache: &mut CommonMarkCache| {
            egui::Frame::new()
                .fill(Color32::WHITE)
                .stroke(Stroke::new(1.0, LINE))
                .corner_radius(CornerRadius::same(6))
                .inner_margin(Margin::same(12))
                .show(ui, |ui| {
                    egui::ScrollArea::vertical()
                        .id_salt("previewscroll")
                        .auto_shrink([false, false])
                        .max_height(h - 26.0)
                        .show(ui, |ui| {
                            CommonMarkViewer::new().show(ui, cache, &preview_md);
                        });
                });
        };

        match view {
            ViewMode::Edit => body_editor(ui, ed),
            ViewMode::Preview => preview(ui, md_cache),
            ViewMode::Split => {
                ui.columns(2, |cols| {
                    body_editor(&mut cols[0], ed);
                    preview(&mut cols[1], md_cache);
                });
            }
        }

        if changed {
            ed.last_change = now;
        }
        if let Some((b, a, p)) = fmt {
            self.insert_text(ctx, b, a, p);
        }
        if let Some(p) = prefix {
            self.insert_line_prefix(ctx, p);
        }
        if let Some(s) = snippet_insert {
            self.insert_snippet(ctx, &s);
        }
        if action_save {
            self.save_current();
        }
        if action_delete {
            self.confirm_delete = true;
        }
    }

    // ------------------------------------------------------------ UI: windows

    fn windows(&mut self, ctx: &egui::Context) {
        // delete confirmation
        if self.confirm_delete {
            let title = self.editor.as_ref().map(|e| e.a.title.clone()).unwrap_or_default();
            let mut close = false;
            let mut del = false;
            egui::Window::new("Eintrag löschen?")
                .collapsible(false)
                .resizable(false)
                .anchor(egui::Align2::CENTER_CENTER, Vec2::ZERO)
                .show(ctx, |ui| {
                    ui.label(format!("„{}“ wird gelöscht. Das lässt sich nicht rückgängig machen.", title));
                    ui.add_space(8.0);
                    ui.horizontal(|ui| {
                        if ui.add(egui::Button::new(RichText::new("Löschen").color(Color32::WHITE)).fill(DANGER)).clicked() {
                            del = true;
                        }
                        if ui.button("Abbrechen").clicked() {
                            close = true;
                        }
                    });
                });
            if del {
                self.confirm_delete = false;
                self.delete_current();
            } else if close {
                self.confirm_delete = false;
            }
        }

        // what's new after a sync
        if let Some(news) = self.news.clone() {
            let mut open = true;
            let mut goto = None;
            egui::Window::new("Neu seit der letzten Synchronisierung")
                .open(&mut open)
                .default_width(460.0)
                .collapsible(false)
                .show(ctx, |ui| {
                    if news.is_empty() {
                        ui.label(RichText::new("Von anderen Rechnern kam nichts Neues.").color(MUTED));
                    }
                    egui::ScrollArea::vertical().max_height(360.0).show(ui, |ui| {
                        for e in &news {
                            ui.horizontal(|ui| {
                                let (icon, c) = match e.action.as_str() {
                                    "created" => ("➕ neu", OK),
                                    "deleted" => ("🗑 gelöscht", DANGER),
                                    _ => ("✏ geändert", ACCENT),
                                };
                                ui.label(RichText::new(icon).small().color(c));
                                let t = if e.title.is_empty() { e.id.clone() } else { e.title.clone() };
                                if e.action != "deleted" {
                                    if ui.link(t).clicked() {
                                        goto = Some(e.id.clone());
                                    }
                                } else {
                                    ui.label(t);
                                }
                                ui.label(
                                    RichText::new(format!("{} · {}", e.client, e.time.get(..16).unwrap_or(&e.time).replace('T', " ")))
                                        .small()
                                        .color(MUTED),
                                );
                            });
                        }
                    });
                });
            if let Some(id) = goto {
                self.open_by_id(&id);
            }
            if !open {
                self.news = None;
            }
        }

        if self.show_settings {
            self.settings_window(ctx);
        }
        if self.show_onto {
            self.onto_window(ctx);
        }
        if self.show_snippets {
            self.snippets_window(ctx);
        }
    }

    fn settings_window(&mut self, ctx: &egui::Context) {
        let mut open = true;
        let mut apply = false;
        let mut install = false;
        egui::Window::new("Einstellungen")
            .open(&mut open)
            .default_width(520.0)
            .collapsible(false)
            .show(ctx, |ui| {
                let d = &mut self.settings_draft;
                egui::Grid::new("settings").num_columns(2).spacing([12.0, 10.0]).show(ui, |ui| {
                    ui.label("Datenordner");
                    ui.horizontal(|ui| {
                        let mut s = d.data_dir.display().to_string();
                        if ui.add(egui::TextEdit::singleline(&mut s).desired_width(300.0)).changed() {
                            d.data_dir = PathBuf::from(s);
                        }
                        if ui.button("Wählen …").clicked() {
                            if let Some(p) = rfd::FileDialog::new().set_directory(&d.data_dir).pick_folder() {
                                d.data_dir = p;
                            }
                        }
                    });
                    ui.end_row();
                    ui.label("");
                    ui.label(
                        RichText::new(format!(
                            "Artikel liegen in {}/JJJJ/MM/TT/<name>/index.md",
                            store::CONTENT_DIR
                        ))
                        .small()
                        .color(MUTED),
                    );
                    ui.end_row();

                    ui.label("GitHub-Repository");
                    ui.add(
                        egui::TextEdit::singleline(&mut d.repo_url)
                            .hint_text("git@github.com:name/microblog.git")
                            .desired_width(360.0),
                    );
                    ui.end_row();
                    ui.label("Branch");
                    ui.add(egui::TextEdit::singleline(&mut d.branch).desired_width(120.0));
                    ui.end_row();
                    ui.label("Name dieses Rechners");
                    ui.add(egui::TextEdit::singleline(&mut d.client).desired_width(160.0));
                    ui.end_row();
                    ui.label("");
                    ui.label(
                        RichText::new("Wird in den Transaktionsdateien vermerkt, damit mehrere Rechner sauber abgleichen.")
                            .small()
                            .color(MUTED),
                    );
                    ui.end_row();
                });
                ui.add_space(6.0);
                ui.label(
                    RichText::new("Anmeldung bei GitHub läuft über die Git-Zugangsdaten dieses Rechners (SSH-Schlüssel oder „gh auth login“).")
                        .small()
                        .color(MUTED),
                );
                ui.separator();
                ui.label(RichText::new("Rechtsklick-Menü (macOS)").strong());
                ui.label(
                    RichText::new(format!(
                        "Richtet den Dienst „{}“ ein: Text irgendwo markieren → Rechtsklick → Dienste.",
                        service::SERVICE_NAME
                    ))
                    .small()
                    .color(MUTED),
                );
                if ui.button("Rechtsklick-Dienst einrichten").clicked() {
                    install = true;
                }
                ui.separator();
                ui.horizontal(|ui| {
                    if ui.add(egui::Button::new(RichText::new("Speichern").color(Color32::WHITE)).fill(ACCENT)).clicked() {
                        apply = true;
                    }
                    if ui.button("Datenordner im Finder zeigen").clicked() {
                        let _ = std::fs::create_dir_all(&self.data);
                        let _ = std::process::Command::new(if cfg!(target_os = "windows") { "explorer" } else if cfg!(target_os = "macos") { "open" } else { "xdg-open" })
                            .arg(&self.data)
                            .spawn();
                    }
                });
            });
        if install {
            match service::install() {
                Ok(p) => self.set_status(format!("Rechtsklick-Dienst eingerichtet: {}", p.display()), true),
                Err(e) => self.set_status(format!("Dienst nicht eingerichtet: {e}"), false),
            }
        }
        if apply {
            self.apply_settings();
            open = false;
        }
        self.show_settings = open;
    }

    fn onto_window(&mut self, ctx: &egui::Context) {
        let mut open = true;
        let tags: Vec<String> = self.all_tags().into_iter().collect();
        let mut change: Option<(String, Option<String>)> = None;
        egui::Window::new("Tags ordnen")
            .open(&mut open)
            .default_width(420.0)
            .collapsible(false)
            .show(ctx, |ui| {
                ui.label(
                    RichText::new("Lege für jeden Tag einen Oberbegriff fest. Tags ohne Oberbegriff erscheinen links als Haupttags; die Suche nach einem Oberbegriff findet auch alle Unterbegriffe.")
                        .small()
                        .color(MUTED),
                );
                ui.add_space(6.0);
                egui::ScrollArea::vertical().max_height(420.0).show(ui, |ui| {
                    egui::Grid::new("onto").num_columns(2).striped(true).spacing([16.0, 6.0]).show(ui, |ui| {
                        for t in &tags {
                            ui.label(RichText::new(format!("#{t}")).color(TAGFG));
                            let cur = self.onto.parent(t).map(|s| s.to_string());
                            let label = cur.clone().map(|p| format!("unter #{p}")).unwrap_or_else(|| "— Haupttag —".into());
                            egui::ComboBox::from_id_salt(("parent", t))
                                .selected_text(label)
                                .width(180.0)
                                .show_ui(ui, |ui| {
                                    if ui.selectable_label(cur.is_none(), "— Haupttag —").clicked() {
                                        change = Some((t.clone(), None));
                                    }
                                    for p in &tags {
                                        if p == t || self.onto.would_cycle(t, p) {
                                            continue;
                                        }
                                        if ui.selectable_label(cur.as_deref() == Some(p), format!("#{p}")).clicked() {
                                            change = Some((t.clone(), Some(p.clone())));
                                        }
                                    }
                                });
                            ui.end_row();
                        }
                    });
                });
            });
        if let Some((t, p)) = change {
            match p {
                Some(p) => {
                    self.onto.parents.insert(t, p.clone());
                    self.expanded.insert(p);
                }
                None => {
                    self.onto.parents.remove(&t);
                }
            }
            match self.onto.save(&self.data) {
                Ok(()) => self.set_status("Tag-Ordnung gespeichert.", true),
                Err(e) => self.set_status(format!("Tag-Ordnung nicht gespeichert: {e}"), false),
            }
        }
        self.show_onto = open;
    }

    fn snippets_window(&mut self, ctx: &egui::Context) {
        let mut open = true;
        let mut insert = None;
        let mut remove = None;
        let mut add = false;
        egui::Window::new("Snippets")
            .open(&mut open)
            .default_width(420.0)
            .default_pos(ctx.screen_rect().right_top() + Vec2::new(-460.0, 70.0))
            .collapsible(false)
            .show(ctx, |ui| {
                ui.label(
                    RichText::new("Kleine Textbausteine. Neue kommen über Rechtsklick → Dienste → „Als Microblog-Snippet speichern“ oder hier.")
                        .small()
                        .color(MUTED),
                );
                ui.add(
                    egui::TextEdit::multiline(&mut self.new_snippet)
                        .hint_text("Neues Snippet …")
                        .desired_rows(2)
                        .desired_width(f32::INFINITY),
                );
                if ui.button("➕ Hinzufügen").clicked() {
                    add = true;
                }
                ui.separator();
                egui::ScrollArea::vertical().max_height(360.0).show(ui, |ui| {
                    if self.snippets.is_empty() {
                        ui.label(RichText::new("Noch keine Snippets.").color(MUTED));
                    }
                    for (i, s) in self.snippets.iter().enumerate() {
                        egui::Frame::new()
                            .fill(LISTBG)
                            .stroke(Stroke::new(1.0, LINE))
                            .corner_radius(CornerRadius::same(6))
                            .inner_margin(Margin::same(8))
                            .show(ui, |ui| {
                                ui.set_width(ui.available_width());
                                ui.label(short(&s.text, 220));
                                ui.horizontal(|ui| {
                                    ui.label(
                                        RichText::new(format!("{} · {}", s.source, s.created.get(..16).unwrap_or(&s.created).replace('T', " ")))
                                            .small()
                                            .color(MUTED),
                                    );
                                    ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                                        if ui.small_button("🗑").on_hover_text("Löschen").clicked() {
                                            remove = Some(i);
                                        }
                                        if ui.small_button("Kopieren").clicked() {
                                            ui.ctx().copy_text(s.text.clone());
                                        }
                                        if ui.small_button("Einfügen").clicked() {
                                            insert = Some(s.text.clone());
                                        }
                                    });
                                });
                            });
                        ui.add_space(4.0);
                    }
                });
            });
        if add && !self.new_snippet.trim().is_empty() {
            match store::add_snippet(&self.data, &self.new_snippet, "App") {
                Ok(()) => {
                    self.new_snippet.clear();
                    self.snippets = store::load_snippets(&self.data);
                    self.snippets_mtime = mtime(&store::snippets_path(&self.data));
                }
                Err(e) => self.set_status(format!("Snippet nicht gespeichert: {e}"), false),
            }
        }
        if let Some(i) = remove {
            self.snippets.remove(i);
            let _ = store::save_snippets(&self.data, &self.snippets);
            self.snippets_mtime = mtime(&store::snippets_path(&self.data));
        }
        if let Some(t) = insert {
            self.insert_snippet(ctx, &t);
        }
        self.show_snippets = open;
    }
}

impl eframe::App for MicroblogApp {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        self.handle_tray(ctx);
        self.poll_sync();
        self.watch_files(ctx);
        self.shortcuts(ctx);
        self.close_handling(ctx);
        self.top_bar(ctx);
        self.status_bar(ctx);
        self.tag_panel(ctx);
        self.list_panel(ctx);
        self.editor_panel(ctx);
        self.windows(ctx);
        self.autosave(ctx);
        self.screenshot_step(ctx);
    }

    fn on_exit(&mut self, _gl: Option<&eframe::glow::Context>) {
        self.save_current();
    }
}

// ---------------------------------------------------------------- widgets

/// One row in the tag sidebar. Returns (row clicked, arrow clicked).
fn tag_row(
    ui: &mut egui::Ui,
    label: &str,
    count: usize,
    selected: bool,
    depth: usize,
    expandable: Option<bool>,
) -> (bool, bool) {
    let w = ui.available_width();
    let (rect, resp) = ui.allocate_exact_size(Vec2::new(w, 26.0), Sense::click());
    let p = ui.painter();
    if selected {
        p.rect_filled(rect, CornerRadius::same(6), ACCENT_SOFT);
    } else if resp.hovered() {
        p.rect_filled(rect, CornerRadius::same(6), Color32::from_rgb(229, 231, 235));
    }
    let indent = 6.0 + depth as f32 * 14.0;
    let mut toggled = false;
    let arrow_rect = egui::Rect::from_min_size(rect.min + Vec2::new(indent, 4.0), Vec2::splat(18.0));
    if let Some(open) = expandable {
        p.text(
            arrow_rect.center(),
            egui::Align2::CENTER_CENTER,
            if open { "⏷" } else { "⏵" },
            FontId::proportional(11.0),
            MUTED,
        );
        if resp.clicked() {
            if let Some(pos) = resp.interact_pointer_pos() {
                toggled = arrow_rect.expand(3.0).contains(pos);
            }
        }
    }
    let color = if selected { ACCENT } else { INK };
    p.text(
        egui::pos2(rect.min.x + indent + 20.0, rect.center().y),
        egui::Align2::LEFT_CENTER,
        label,
        FontId::proportional(14.0),
        color,
    );
    p.text(
        egui::pos2(rect.max.x - 8.0, rect.center().y),
        egui::Align2::RIGHT_CENTER,
        count.to_string(),
        FontId::proportional(12.0),
        MUTED,
    );
    (resp.clicked() && !toggled, toggled)
}

fn tag_chip(ui: &mut egui::Ui, t: &str) -> egui::Response {
    ui.add(
        egui::Button::new(RichText::new(format!("#{t}")).small().color(TAGFG))
            .fill(TAGBG)
            .stroke(Stroke::NONE)
            .corner_radius(CornerRadius::same(9)),
    )
}

/// A card in the list: title, date + tags, abstract (max. 3 lines).
/// Returns (card clicked, tag clicked).
fn entry_card(ui: &mut egui::Ui, a: &Article, selected: bool) -> (bool, Option<String>) {
    let mut tag_clicked = None;
    let stroke = if selected { Stroke::new(1.5, ACCENT) } else { Stroke::new(1.0, LINE) };
    let inner = egui::Frame::new()
        .fill(Color32::WHITE)
        .stroke(stroke)
        .corner_radius(CornerRadius::same(8))
        .inner_margin(Margin::symmetric(12, 10))
        .show(ui, |ui| {
            ui.set_width(ui.available_width());
            let title = if a.title.trim().is_empty() { "Ohne Titel" } else { a.title.trim() };
            ui.horizontal(|ui| {
                ui.label(RichText::new(title).size(15.5).strong().color(INK));
                if a.draft {
                    ui.label(RichText::new("Entwurf").small().color(Color32::from_rgb(217, 119, 6)));
                }
            });
            ui.horizontal_wrapped(|ui| {
                ui.spacing_mut().item_spacing.x = 4.0;
                ui.label(RichText::new(a.date.format("%d.%m.%Y · %H:%M").to_string()).small().color(MUTED));
                ui.add_space(4.0);
                for t in &a.tags {
                    if tag_chip(ui, t).clicked() {
                        tag_clicked = Some(t.clone());
                    }
                }
            });
            let text = if a.abstract_.trim().is_empty() {
                first_words(&a.body, 300)
            } else {
                a.abstract_.trim().replace('\n', " ")
            };
            if !text.is_empty() {
                ui.add_space(2.0);
                let mut job = egui::text::LayoutJob::single_section(
                    text,
                    egui::TextFormat {
                        font_id: FontId::proportional(13.5),
                        color: Color32::from_rgb(55, 65, 81),
                        ..Default::default()
                    },
                );
                job.wrap = egui::text::TextWrapping {
                    max_width: ui.available_width(),
                    max_rows: 3,
                    break_anywhere: false,
                    overflow_character: Some('…'),
                };
                let galley = ui.fonts(|f| f.layout_job(job));
                ui.label(galley);
            }
        });
    let resp = ui.interact(inner.response.rect, ui.id().with(("card", &a.id)), Sense::click());
    if resp.hovered() {
        ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
    }
    (resp.clicked() && tag_clicked.is_none(), tag_clicked)
}

// ---------------------------------------------------------------- helpers

fn setup_style(ctx: &egui::Context) {
    let mut v = egui::Visuals::light();
    v.panel_fill = Color32::WHITE;
    v.window_fill = Color32::WHITE;
    v.extreme_bg_color = Color32::WHITE;
    v.selection.bg_fill = ACCENT_SOFT;
    v.selection.stroke = Stroke::new(1.0, ACCENT);
    v.hyperlink_color = ACCENT;
    v.window_corner_radius = CornerRadius::same(10);
    v.widgets.inactive.corner_radius = CornerRadius::same(6);
    v.widgets.hovered.corner_radius = CornerRadius::same(6);
    v.widgets.active.corner_radius = CornerRadius::same(6);
    v.widgets.inactive.weak_bg_fill = Color32::from_rgb(243, 244, 246);
    v.widgets.inactive.bg_stroke = Stroke::new(1.0, LINE);
    ctx.set_visuals(v);
    ctx.style_mut(|s| {
        s.spacing.item_spacing = Vec2::new(8.0, 6.0);
        s.spacing.button_padding = Vec2::new(10.0, 5.0);
        s.text_styles.insert(TextStyle::Body, FontId::proportional(14.0));
        s.text_styles.insert(TextStyle::Button, FontId::proportional(14.0));
        s.text_styles.insert(TextStyle::Small, FontId::proportional(11.5));
        s.text_styles.insert(TextStyle::Monospace, FontId::monospace(13.5));
    });
}

fn native_view(cc: &eframe::CreationContext<'_>) -> usize {
    use raw_window_handle::{HasWindowHandle, RawWindowHandle};
    match cc.window_handle() {
        Ok(h) => match h.as_raw() {
            RawWindowHandle::AppKit(a) => a.ns_view.as_ptr() as usize,
            _ => 0,
        },
        Err(_) => 0,
    }
}

fn set_body_cursor(ctx: &egui::Context, start: usize, end: usize) {
    let id = egui::Id::new("body_editor");
    if let Some(mut state) = egui::TextEdit::load_state(ctx, id) {
        state.cursor.set_char_range(Some(egui::text::CCursorRange::two(
            egui::text::CCursor::new(start),
            egui::text::CCursor::new(end),
        )));
        state.store(ctx, id);
    }
}

fn byte_idx(s: &str, ci: usize) -> usize {
    s.char_indices().nth(ci).map(|(b, _)| b).unwrap_or(s.len())
}

fn short(s: &str, n: usize) -> String {
    let one = s.split_whitespace().collect::<Vec<_>>().join(" ");
    if one.chars().count() > n {
        format!("{}…", one.chars().take(n).collect::<String>())
    } else {
        one
    }
}

fn first_words(body: &str, n: usize) -> String {
    let text: String = body
        .lines()
        .filter(|l| !l.trim_start().starts_with("```") && !l.trim().is_empty())
        .map(|l| l.trim_start_matches(['#', '>', '-', '*', ' ']).trim())
        .collect::<Vec<_>>()
        .join(" ");
    short(&text, n)
}

fn mtime(p: &std::path::Path) -> Option<SystemTime> {
    std::fs::metadata(p).ok().and_then(|m| m.modified().ok())
}

