                let ed = self.editor.as_ref().unwrap();
                ui.horizontal(|ui| {
                    if ui
                        .add(egui::Button::new(RichText::new("💾  Speichern").color(Color32::WHITE)).fill(ACCENT))
                        .on_hover_text("⌘S – wird auch automatisch gespeichert")
