                let q = store::normalize_tag(&ed.tag_input);
                if !q.is_empty() {
                    let sugg: Vec<String> = all_tags
                        .iter()
                        .filter(|t| t.contains(q.as_str()) && !ed.a.tags.contains(t))
                        .take(5)
                        .cloned()
                        .collect();
                    for t in sugg {
                        let b = egui::Button::new(RichText::new(format!("+ #{t}")).small().color(MUTED)).frame(false);
                        if ui.add(b).clicked() {
                            ed.a.tags.push(t);
                            ed.tag_input.clear();
                            changed = true;
                        }
                    }
                }
