    fn delete_window(&mut self, ctx: &egui::Context) {
        let title = self.editor.as_ref().map(|e| e.a.title.clone()).unwrap_or_default();
        let mut close = false;
        let mut del = false;
        egui::Window::new("Eintrag löschen?")
            .collapsible(false)
            .resizable(false)
