                ui.label(format!("„{title}“ wird gelöscht. Das lässt sich nicht rückgängig machen."));
                ui.add_space(8.0);
                ui.horizontal(|ui| {
                    let b = egui::Button::new(RichText::new("Löschen").color(Color32::WHITE)).fill(DANGER);
                    if ui.add(b).clicked() {
                        del = true;
                    }
                    if ui.button("Abbrechen").clicked() {
                        close = true;
