                    ui.end_row();
                    ui.label("Name dieses Rechners");
                    ui.add(egui::TextEdit::singleline(&mut d.client).desired_width(160.0));
                    ui.end_row();
                    ui.label("");
                    ui.label(
                        RichText::new("Steht in den Transaktionsdateien, damit mehrere Rechner sauber abgleichen.")
                            .small()
                            .color(MUTED),
                    );
                    ui.end_row();
                });
                ui.add_space(6.0);
                ui.label(
                    RichText::new(
