694	/// Reads every `index.md` below `content/`.
695	
696	// ---------------------------------------------------------------- transactions
697	
698	#[derive(Clone, Debug, Serialize, Deserialize)]
699	pub struct TxEntry {
700	    pub time: String,
701	    pub id: String,
702	    pub action: String,
703	    pub path: String,
704	    #[serde(default)]
705	    pub title: String,
706	    #[serde(default)]
707	    pub client: String,
708	}
709	
710	#[derive(Clone, Debug, Default, Serialize, Deserialize)]
711	#[serde(default)]
712	pub struct TxDay {
713	    pub date: String,
714	    pub client: String,
715	    pub entries: Vec<TxEntry>,
716	}
717	
718	fn tx_file(data: &Path, day: &chrono::NaiveDate, client: &str) -> PathBuf {
719	    data.join(TX_DIR)
720	        .join(day.format("%Y").to_string())
721	        .join(day.format("%m").to_string())
722	        .join(format!("{}_{}.json", day.format("%Y-%m-%d"), client))
723	}
724	
725	/// Appends one change to today's transaction file of this client.
726	/// Several saves of the same article on one day are folded into one entry.
727	pub fn log_tx(data: &Path, client: &str, a: &Article, action: &str) -> Result<(), String> {
728	    let now = Local::now();
729	    let day = now.date_naive();
730	    let f = tx_file(data, &day, client);
731	    let mut txd: TxDay = fs::read_to_string(&f)
732	        .ok()
733	        .and_then(|s| serde_json::from_str(&s).ok())
734	        .unwrap_or_default();
735	    txd.date = day.format("%Y-%m-%d").to_string();
736	    txd.client = client.to_string();
737	    let entry = TxEntry {
738	        time: now.to_rfc3339_opts(chrono::SecondsFormat::Secs, false),
739	        id: a.id.clone(),
740	        action: action.to_string(),
741	        path: format!("{}/index.md", a.rel_dir),
742	        title: a.title.clone(),
743	        client: client.to_string(),
744	    };
745	    if let Some(last) = txd.entries.iter_mut().rev().find(|e| e.id == a.id) {
746	        if action == "updated" && (last.action == "updated" || last.action == "created") {
747	            last.time = entry.time;
748	            last.title = entry.title;
749	            write_json(&f, &txd)?;
750	            return Ok(());
751	        }
752	    }
753	    txd.entries.push(entry);
754	    write_json(&f, &txd)
755	}
756	
757	fn write_json<T: Serialize>(f: &Path, v: &T) -> Result<(), String> {
758	    if let Some(d) = f.parent() {
759	        fs::create_dir_all(d).map_err(|e| e.to_string())?;
760	    }
761	    let s = serde_json::to_string_pretty(v).map_err(|e| e.to_string())?;
762	    fs::write(f, s).map_err(|e| e.to_string())
763	}
764	
765	/// All transaction entries (from every client) newer than `since`, newest first.
766	pub fn tx_since(data: &Path, since: Option<&str>) -> Vec<TxEntry> {
767	    let since = since.and_then(|s| DateTime::parse_from_rfc3339(s).ok());
768	    let mut out = Vec::new();
769	    walk(&data.join(TX_DIR), &mut |p| {
770	        if p.extension().map(|e| e == "json").unwrap_or(false) {
771	            if let Some(txd) = fs::read_to_string(p)
772	                .ok()
773	                .and_then(|s| serde_json::from_str::<TxDay>(&s).ok())
774	            {
775	                for mut e in txd.entries {
776	                    if e.client.is_empty() {
777	                        e.client = txd.client.clone();
778	                    }
779	                    let t = DateTime::parse_from_rfc3339(&e.time).ok();
780	                    let newer = match (since, t) {
781	                        (Some(s), Some(t)) => t > s,
782	                        _ => since.is_none(),
783	                    };
784	                    if newer {
785	                        out.push(e);
786	                    }
787	                }
788	            }
789	        }
790	    });
791	    out.sort_by(|a, b| b.time.cmp(&a.time));
792	    out
793	}
794	
795	// ---------------------------------------------------------------- snippets

