pub fn article_dirs(base: &Path, cfg: &Config) -> BTreeSet<String> {
    let mut out = BTreeSet::new();
    let sub = cfg.content_subdir.trim().trim_matches('/');
    let root = if sub.is_empty() { base.to_path_buf() } else { base.join(sub) };
    walk(&root, &mut |p| {
        if p.file_name().map(|n| n == "index.md").unwrap_or(false) {
            if let Some(rel) = p.parent().and_then(|d| d.strip_prefix(base).ok()) {
                let rel = rel.to_string_lossy().replace('\\', "/");
                if !rel.is_empty() {
                    out.insert(rel);
                }
            }
        }
    });
    out
}

