//! Sync between the local data folder and a second local folder (e.g. the Hugo blog, which
//! itself may be kept in Git by the person). No network, no Git here.
//!
//! Normal sync:
//!   1. read the sync folder's `transactions/transaction-YYYY-MM-dd-HH-mm.json` files, starting at
//!      the last processed stamp (several files can share one stamp), and copy the folders listed
//!      there into the local folder (new ones are imported, existing ones overwritten);
//!   2. copy the local changes (pending list) into the sync folder and describe them in a new
//!      transaction file;
//!   3. remember the last processed transaction file.
//!
//! Full sync: compares every article folder on both sides, copies what is missing on either side,
//! newer wins where both differ, writes a transaction file for everything written to the sync
//! folder and marks all existing transaction files as processed.

use crate::store::{self, Config, Ontology, Snippet, TxEntry};
use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::Path;

pub struct SyncResult {
    pub log: Vec<String>,
    /// changes that came from the sync folder (shown as "what's new")
    pub imported: Vec<TxEntry>,
    pub last_tx: String,
    pub last_tx_files: Vec<String>,
}

fn check(cfg: &Config) -> Result<(), String> {
    let sync = &cfg.sync_dir;
    if sync.as_os_str().is_empty() {
        return Err("Bitte zuerst in den Einstellungen einen Sync-Ordner wählen.".into());
    }
    if !sync.is_dir() {
        return Err(format!("Sync-Ordner nicht gefunden: {}", sync.display()));
    }
    let a = fs::canonicalize(&cfg.data_dir).unwrap_or(cfg.data_dir.clone());
    let b = fs::canonicalize(sync).unwrap_or(sync.clone());
    if a == b {
        return Err("Datenordner und Sync-Ordner sind derselbe Ordner.".into());
    }
    fs::create_dir_all(&cfg.data_dir).map_err(|e| e.to_string())?;
    Ok(())
}

/// Replaces `dst` with a copy of `src` (all files of the article folder, incl. images).
fn mirror(src: &Path, dst: &Path) -> Result<(), String> {
    if dst.exists() {
        fs::remove_dir_all(dst).map_err(|e| format!("{}: {e}", dst.display()))?;
    }
    copy_dir(src, dst)
}

fn copy_dir(src: &Path, dst: &Path) -> Result<(), String> {
    fs::create_dir_all(dst).map_err(|e| format!("{}: {e}", dst.display()))?;
    for e in fs::read_dir(src).map_err(|e| format!("{}: {e}", src.display()))?.flatten() {
        let name = e.file_name();
        if name.to_string_lossy().starts_with('.') {
            continue;
        }
        let p = e.path();
        if p.is_dir() {
            copy_dir(&p, &dst.join(&name))?;
        } else {
            fs::copy(&p, dst.join(&name)).map_err(|e| format!("{}: {e}", p.display()))?;
        }
    }
    Ok(())
}

fn remove_dir(base: &Path, rel: &str) -> Result<bool, String> {
    let d = base.join(rel);
    if d.is_dir() {
        fs::remove_dir_all(&d).map_err(|e| format!("{}: {e}", d.display()))?;
        return Ok(true);
    }
    Ok(false)
}

/// Same files with the same contents?
fn same_dir(a: &Path, b: &Path) -> bool {
    fn files(d: &Path, prefix: &str, out: &mut BTreeMap<String, Vec<u8>>) {
        let Ok(rd) = fs::read_dir(d) else { return };
        for e in rd.flatten() {
            let n = e.file_name().to_string_lossy().to_string();
            if n.starts_with('.') {
                continue;
            }
            let p = e.path();
            if p.is_dir() {
                files(&p, &format!("{prefix}{n}/"), out);
            } else {
                out.insert(format!("{prefix}{n}"), fs::read(&p).unwrap_or_default());
            }
        }
    }
    let (mut fa, mut fb) = (BTreeMap::new(), BTreeMap::new());
    files(a, "", &mut fa);
    files(b, "", &mut fb);
    fa == fb
}

fn modified(dir: &Path) -> std::time::SystemTime {
    fs::metadata(dir.join("index.md"))
        .and_then(|m| m.modified())
        .unwrap_or(std::time::UNIX_EPOCH)
}

fn entry_for(base: &Path, rel: &str, action: &str, cfg: &Config) -> TxEntry {
    let (id, title) = fs::read_to_string(base.join(rel).join("index.md"))
        .map(|t| {
            let a = store::parse_article(&t, rel, cfg);
            (a.id, a.title)
        })
        .unwrap_or_else(|_| (rel.replace('/', "-"), String::new()));
    TxEntry {
        time: chrono::Local::now().to_rfc3339_opts(chrono::SecondsFormat::Secs, false),
        id,
        action: action.into(),
        path: rel.into(),
