        let name = store::write_tx_file(sync, &cfg.client, &written)?;
        if let Some(stamp) = store::tx_stamp(&name) {
            mark(&stamp, &name, &mut last_tx, &mut last_files);
        }
        log.push(format!("{} lokale Änderung(en) geschrieben ({name}).", written.len()));
    } else {
        log.push("Keine lokalen Änderungen.".into());
    }
    store::save_pending(data, &[])?;
    merge_extras(cfg);

    Ok(SyncResult { log, imported, last_tx, last_tx_files: last_files })
}

pub fn full_sync(cfg: &Config) -> Result<SyncResult, String> {
    check(cfg)?;
    let (data, sync) = (&cfg.data_dir, &cfg.sync_dir);
    let pending = store::load_pending(data);
    let pending_dirs: BTreeSet<String> = pending.iter().map(|e| e.dir()).collect();

    // deletions made here go out first
    let mut written = Vec::new();
    for e in pending.iter().filter(|e| e.action == "deleted") {
        remove_dir(sync, &e.dir())?;
        written.push(e.clone());
    }

    let local = store::article_dirs(data, cfg);
    let remote = store::article_dirs(sync, cfg);
    let mut imported = Vec::new();
    let (mut n_in, mut n_out) = (0, 0);
    for dir in local.union(&remote) {
        let (l, r) = (data.join(dir), sync.join(dir));
        match (local.contains(dir), remote.contains(dir)) {
            (false, true) => {
                mirror(&r, &l)?;
                imported.push(entry_for(sync, dir, "created", cfg));
                n_in += 1;
            }
            (true, false) => {
                mirror(&l, &r)?;
                written.push(entry_for(data, dir, "created", cfg));
                n_out += 1;
            }
            _ => {
                if same_dir(&l, &r) {
                    continue;
                }
                if pending_dirs.contains(dir) || modified(&l) >= modified(&r) {
                    mirror(&l, &r)?;
                    written.push(entry_for(data, dir, "updated", cfg));
                    n_out += 1;
                } else {
                    mirror(&r, &l)?;
                    imported.push(entry_for(sync, dir, "updated", cfg));
                    n_in += 1;
                }
            }
        }
    }

    let mut log = vec![format!(
        "Vollsynchronisierung: {} Artikel hier, {} im Sync-Ordner – {n_in} geholt, {n_out} geschrieben.",
        local.len(),
        remote.len()
    )];
    // everything that exists so far counts as processed
    let mut files = store::list_tx_files(sync);
    if !written.is_empty() {
        let name = store::write_tx_file(sync, &cfg.client, &written)?;
        log.push(format!("Transaktionsdatei geschrieben: {name}"));
        files = store::list_tx_files(sync);
    }
    let last_tx = files.last().map(|(s, _)| s.clone()).unwrap_or_default();
    let last_tx_files = files.iter().filter(|(s, _)| *s == last_tx).map(|(_, n)| n.clone()).collect();
    store::save_pending(data, &[])?;
    merge_extras(cfg);

    Ok(SyncResult { log, imported, last_tx, last_tx_files })
}

