//! Button-triggered sync of the data folder with a GitHub repository, using the `git` command.
//! Order: commit local changes -> fetch -> merge remote changes -> push.

use std::path::Path;
use std::process::Command;

pub struct SyncResult {
    pub log: Vec<String>,
}

fn git(dir: &Path, args: &[&str]) -> Result<String, String> {
    let out = Command::new("git")
        .args(args)
        .current_dir(dir)
        .env("GIT_TERMINAL_PROMPT", "0")
        .output()
        .map_err(|e| format!("git konnte nicht gestartet werden: {e}"))?;
    let stdout = String::from_utf8_lossy(&out.stdout).trim().to_string();
    let stderr = String::from_utf8_lossy(&out.stderr).trim().to_string();
    if out.status.success() {
        Ok(stdout)
    } else {
        Err(format!(
            "git {}: {}",
            args.first().unwrap_or(&""),
            if stderr.is_empty() { stdout } else { stderr }
        ))
    }
}

pub fn sync(data: &Path, repo_url: &str, branch: &str, client: &str) -> Result<SyncResult, String> {
    let mut log = Vec::new();
    let branch = if branch.trim().is_empty() { "main" } else { branch.trim() };
    if repo_url.trim().is_empty() {
        return Err("Bitte zuerst in den Einstellungen die Adresse des GitHub-Repositorys eintragen.".into());
    }
    std::fs::create_dir_all(data).map_err(|e| e.to_string())?;

    if !data.join(".git").exists() {
        git(data, &["init"])?;
        git(data, &["symbolic-ref", "HEAD", &format!("refs/heads/{branch}")])?;
        log.push("Neues Git-Repository im Datenordner angelegt.".into());
    }
    let gi = data.join(".gitignore");
    if !gi.exists() {
        let _ = std::fs::write(&gi, ".DS_Store\n*.tmp\n");
    }

    match git(data, &["remote", "get-url", "origin"]) {
        Ok(url) if url.trim() == repo_url.trim() => {}
        Ok(_) => {
            git(data, &["remote", "set-url", "origin", repo_url.trim()])?;
        }
        Err(_) => {
            git(data, &["remote", "add", "origin", repo_url.trim()])?;
        }
    }

    // identity for commits if the computer has none configured
    let has_identity = git(data, &["config", "user.email"]).map(|s| !s.is_empty()).unwrap_or(false);
    let ident: Vec<String> = if has_identity {
        vec![]
    } else {
        vec![
            "-c".into(),
            format!("user.name=Microblog ({client})"),
            "-c".into(),
            format!("user.email={client}@microblog.local"),
        ]
    };
    let with_ident = |args: &[&str]| -> Result<String, String> {
        let mut all: Vec<&str> = ident.iter().map(|s| s.as_str()).collect();
        all.extend_from_slice(args);
        git(data, &all)
    };

    // 1) commit local changes
    git(data, &["add", "-A"])?;
    let status = git(data, &["status", "--porcelain"])?;
    if !status.is_empty() {
        let n = status.lines().count();
        let msg = format!(
            "microblog: {} Änderung(en) von {} ({})",
            n,
            client,
            chrono::Local::now().format("%Y-%m-%d %H:%M")
        );
        with_ident(&["commit", "-q", "-m", &msg])?;
        log.push(format!("{n} lokale Änderung(en) gespeichert."));
    } else {
        log.push("Keine lokalen Änderungen.".into());
    }

    // 2) fetch
    git(data, &["fetch", "-q", "origin"])?;
    let remote_ref = format!("origin/{branch}");
    let remote_exists = git(data, &["rev-parse", "--verify", "-q", &remote_ref]).is_ok();
    let local_exists = git(data, &["rev-parse", "--verify", "-q", "HEAD"]).is_ok();

    // 3) merge remote changes
    if remote_exists {
        if local_exists {
            let before = git(data, &["rev-parse", "HEAD"])?;
            if let Err(e) = with_ident(&[
                "merge",
                "--no-edit",
                "--allow-unrelated-histories",
                "-q",
                &remote_ref,
            ]) {
                let conflicts = git(data, &["diff", "--name-only", "--diff-filter=U"]).unwrap_or_default();
                let _ = git(data, &["merge", "--abort"]);
                return Err(if conflicts.is_empty() {
                    e
                } else {
                    format!(
                        "Konflikt beim Zusammenführen – diese Dateien wurden auf beiden Seiten geändert:\n{conflicts}"
                    )
                });
            }
            let after = git(data, &["rev-parse", "HEAD"])?;
            if before != after {
                log.push("Neue Daten aus dem Repository geholt.".into());
            } else {
                log.push("Im Repository war nichts Neues.".into());
            }
        } else {
            git(data, &["checkout", "-q", "-B", branch, &remote_ref])?;
            log.push("Daten aus dem Repository übernommen.".into());
        }
    }

    // 4) push
    if git(data, &["rev-parse", "--verify", "-q", "HEAD"]).is_ok() {
        git(data, &["push", "-q", "-u", "origin", branch])?;
        log.push("Lokale Einträge ins Repository geschrieben.".into());
    }

    Ok(SyncResult { log })
}

